window.FS_DATA=window.FS_DATA||{};FS_DATA["tetetingullshi"]={"title":"Tetëtingullshi Ngjallësor","tones":[{"n":"Tingulli i Parë","sections":[{"k":"thirrtoret","part":"mbremesore","title":"Vargëzimet e Thirrtoreve","blocks":[{"t":"p","x":"Lutjet tona të mbrëmjes priti, o Zot i shenjtë, dhe falna ndjesë mëkatesh, se ti je i vetmi që rrëfeve në botë Ngjalljen."},{"t":"p","x":"Rrethoni Sionin, o popuj, dhe vëreni në mes dhe jepini lavdi në të atij që u ngjall prej së vdekurish, se ai është Perëndia ynë, që na çliroi nga paudhësitë tona."},{"t":"p","x":"Ejani, o popuj, të përhimnojmë dhe t’i falemi Krishtit, duke lavdëruar ngjalljen e tij prej së vdekurish, se ai është Perëndia ynë, që çliroi botën prej kurthit të armikut."},{"t":"p","x":"Dëfreni, o qiej, buçisni, o themele të dheut, thërrisni, o male, me ngazëllim, se ja Emanueli mbërtheu mëkatet tona në Kryq dhe vrau vdekjen ai që fal jetë, duke ngjallur Adamin si Njeridashës."},{"t":"p","x":"Atë që u kryqëzua për ne trupërisht duke dashur, që pësoi dhe u varros dhe u ngjall së vdekurish, le ta himnojmë duke thënë: Mbështete në Orthodhoksi Kishën tënde, o Krisht, paqësonaje jetën, si i Mirë dhe Njeridashës."},{"t":"p","x":"Duke qëndruar pranë varrit tënd jetëpritës, ne të pavyerit i blatojmë lavdërim dhembshurisë sate të pashprehshme, o Krisht, Perëndia ynë, se denjove Kryq dhe vdekje, o i pamëkatshëm, që t’i dhurosh botës ngjalljen si Njeridashës."},{"t":"p","x":"Fjalën e bashkëpanisshme dhe të bashkamshuar me Atin, që lindi pa shpjegim prej gjirit virgjëror, dhe denjoi për ne Kryq dhe vdekje duke dashur, dhe u ngjall me lavdi, le ta himnojmë duke thënë: Lavdi më ty, o Zot jetëdhënës, o Shpëtimtar i shpirtrave tanë."}]},{"k":"dogmatiku","part":"mbremesore","title":"Hyjlindësorja Dogmatike","blocks":[{"t":"p","x":"Lavdinë e përbotshme, që u mboll prej njerëzve dhe lindi Kryezotin, derën qiellore, le ta himnojmë, Marinë, Virgjëreshën, këngën e engjëjve dhe zbukurimin e besnikëve, se ajo u tregua qiell dhe tempull i Hyjnisë. Ajo, duke rrëzuar murin ndarës të armiqësisë, solli paqen në vend të saj dhe e çeli mbretërinë. Duke pasur, pra, këtë si spirancë të besës, kemi mbrojtës Zotin që lindi prej saj. Le të ketë, pra, kurajë, le të ketë kurajë populli i Perëndisë, se ai do t’i luftojë armiqtë, si i Tërëfuqishëm."}]},{"k":"pasvargjet","part":"mbremesore","title":"Pasvargjet","blocks":[{"t":"p","x":"Me anën e Pësimit tënd, o Krisht, u çliruam prej pësimeve, dhe me anën e Ngjalljes sate u çliruam prej prishjes. O Zot, lavdi më ty."},{"t":"p","x":"Le të gëzohet krijesa, le të dëfrejnë qiejt, le të duartrokasin kombet me ngazëllim, se Krishti, Shpëtimtari ynë, mbërtheu mëkatet tona në Kryq dhe, duke vrarë vdekjen, na dhuroi jetën, duke ngjallur Adamin e rënë me gjith’ gjininë e tij si Njeridashës."},{"t":"p","x":"Duke qenë Mbret i qiellit dhe i dheut, o i pakuptueshëm, u kryqëzove duke dashur nga njeridashja; dhe, kur të takoi, Hadhi përposhtë u hidhërua; dhe shpirtrat e të drejtëve që të prisnin, u ngazëlluan; dhe, kur të pa Adami në të përposhtmet ty, Krijuesin, u ngjall. O çudi! Si shijoi vdekje jeta e të gjithëve? Ngaqë deshi, që të ndriçojë botën, e cila thërret dhe thotë: O Zot, që u ngjalle së vdekurish, lavdi më ty."},{"t":"p","x":"Gratë miroprurëse, duke sjellë miro, me nxitim dhe me vajtim erdhën te varri yt; dhe, si nuk e gjetën trupin tënd të pacenuar dhe mësuan prej engjëllit çudinë e re dhe të mahnitshme, u thoshin apostujve: U ngjall Zoti dhe i fali botës përdëllimin e madh."},{"t":"sub","x":"Lavdi dhe tani"},{"t":"sub","x":"Hyjlindësorja"},{"t":"p","x":"Ja ku u përmbush profecia e Isaisë: se Virgjëreshë linde dhe pas lindjes mbete si përpara lindjes; se ai që lindi, ishte Perëndi, prandaj e përtëriti natyrën. Po, o Nënë e Perëndisë, mos i hidh tej lutjet e shërbëtorëve të tu, që të blatohen te tempulli yt. Po, sikundër mban në prehrin tënd të Mëshirshmin, mëshiroji përgjëruesit e tu dhe ndërmjeto që të shpëtohen shpirtrat tanë."}]},{"k":"perleshorja","part":"mengjesore","title":"Përlëshorja Ngjallësore","blocks":[{"t":"p","x":"Guri kur u vulos prej judenjve dhe ushtarët ruanin trupin tënd të pacenuar, u ngjalle pas tri ditësh, Shpëtimtar, duke i dhuruar botës jetën. Prandaj fuqit’ e qiejve të thërrisnin, Jetëdhënës: Lavdi Ngjalljes sate, o Krisht; lavdi Mbretërisë sate; lavdi Ekonomisë sate, i vetmi Njeridashës."}]},{"k":"hyjlindesorja","part":"mengjesore","title":"Hyjlindësorja Ngjallësore","blocks":[{"t":"p","x":"Gabrieli kur të tha, Virgjëreshë, “Gëzohu”, bashkë me zërin mishërohej Zoti i gjithësisë te ti arka e shenjtë, siç tha Davidi i drejtë. U tregove më e gjerë se qiejt, duke mbajtur Krijuesin tënd. Lavdi atij që ndenji te ti; lavdi atij që lindi prej teje; lavdi atij që na çliroi me lindjen tënde."}]},{"k":"ndenjesoret1","part":"mengjesore","title":"Pas Stihologjisë së parë, Ndenjësoret","blocks":[{"t":"sub","x":"Ton tafon su Sotir"},{"t":"p","x":"Ushtarët, Shpëtimtar, që të ruanin varrin, nga engjëlli q’u duk, si të vdekur u bënë, kur ndriti dhe u lajmëroi grave Ngjalljen me gaz të madh. Ty të japim lavd, o shkatërrues i prishjes, dhe mëgjunjazi të biem ty, Perëndisë, që u ngjalle së vdekurish."},{"t":"sub","x":"Lavdi"},{"t":"sub","x":"E njëjtë"},{"t":"p","x":"Mbërthehesh përmbi Kryq, Shpëtimtar, duke dashur, dhe vihesh në një varr, Perëndi jetëdhënës, e shtyp dhe krejt e shkatërron të mallkuarin Hadh përdhe, tmerri pra i kap të gjithë djajt’ e Skëterrës, dhe të gjith’ i ngre sa kishin vdekur qëmoti, i vetmi mik i njerëzve."},{"t":"sub","x":"Tani"},{"t":"sub","x":"E njëjtë"},{"t":"p","x":"Si Nën’ të Zotit Krisht, ne besnikët të lusim, o Zonjë Shën Mari, Virgjëreshë pas lindjes, përikim pra te ti me mall, si e mirë që je për ne; ty të kemi pra, ne mëkatarët si mbrojtje prej rreziqeve, dhe shpëtimtare në ngasje, o Zonjë Hyjlindëse."}]},{"k":"ndenjesoret2","part":"mengjesore","title":"Pas Stihologjisë së dytë, Ndenjësoret","blocks":[{"t":"sub","x":"Tu lithu sfragjisthentos"},{"t":"p","x":"Drejt varrit qëmenatë miroprurëset shkuan edhe u tmerruan kur panë dy engjëj të shkëlqyer, se varri lëshonte shkrepëtim’, çudia mendjen ua turbulloi; edhe rendën dhe dishepujve në qytet me gaz ua çuan lajmin: Skëterrën e plaçkiti Zoti Krisht dhe i ngjalli të varrosurit, edhe tutje e largoj me Kryq frikën e gjyqeve."},{"t":"sub","x":"Lavdi"},{"t":"sub","x":"E njëjtë"},{"t":"p","x":"Mbi Kryq pra u mbërtheve ti, o jet’ e pasosur, dhe në varr u shtrive i vdekur, o Krisht, o Jetëdhënës; u ngjalle të tretën dit’, o Zot, dhe jetën u dhurove njerëzve. Prandaj pra ushtrit’ engjëllore lart të thërrisnin, Jetëdhënës. Lavdi më ty që hoqe keq për ne, u ngjalle dhe hipe lart në q’ell, dhe kujdesesh gjithnjë për ne, o mik i njerëzve."},{"t":"sub","x":"Tani"},{"t":"sub","x":"Ton tafon su Sotir"},{"t":"p","x":"O Zonjë Shën Mari, en’ e zgjedhur e Zotit, na ngri dhe na shpëto ne të mjerët që humbëm në pellg të dëshpërimeve dhe në pus të mëkateve, ti je ndihmëse edhe përkrahëse e fortë, dhe mbrojtje e besnikëve."}]},{"k":"degjimi","part":"mengjesore","title":"Dëgjimi","blocks":[{"t":"p","x":"Pendimi i kusarit rrëmbeu Parajsën, ndërsa vajtimi i miroprurëseve lajmëroi gëzimin që u ngjalle, o Krisht Perëndi, dhe i dhurove botës përdëllimin e madh."}]},{"k":"shkallesat","part":"mengjesore","title":"Shkallesat","blocks":[{"t":"sub","x":"Antifoni i parë"},{"t":"p","x":"Në hidhërimin tim të thërres, o Zot, dëgjoji rënkimet e mia."},{"t":"p","x":"Eremitët kanë dashuri të pasosur hyjnore, se janë jashtë botës së kotë."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Shpirtit të Shenjtë i ka hije nderi e lavdia, si dhe Atit bashk’ me Birin, prandaj le t’i këndojmë të vetmit pushtet trinisor."},{"t":"sub","x":"Antifoni i dytë"},{"t":"p","x":"Si më ngjite mbi malet e ligjeve të tua, ndritmë me virtyte, o Perëndi, që të të himnoj."},{"t":"p","x":"Merrmë me dorën e djathtë ti, o Fjalë, dhe ruajmë dhe mbromë që të mos më djegë zjarri i mëkatit."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Me anën e Shpirtit të Shenjtë përtëritet tërë Krijesa dhe kthehet si më parë, se ësht’ i njëfuqishëm me Atin e me Fjalën."},{"t":"sub","x":"Antifoni i tretë"},{"t":"p","x":"Me ata që më kanë thënë: “Le të ecim në oborret e Zotit”, më dëfreu shpirti dhe m’u gëzua zemra."},{"t":"p","x":"Në shtëpinë e Davidit është frik’ e madhe, se atje do të vihen frone dhe do të gjykohen të gjitha racat dhe gjuhët e dheut."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Shpirtit të Shenjtë duhet t’i blatojmë nder dhe adhurim, lavdi dhe fuqi, siç i ka hije Atit e Birit, se Trinia është një nga Natyra, por jo nga Personat."}]},{"k":"paravargu","part":"mengjesore","title":"Paravargu","blocks":[{"t":"p","x":"Tani do të ngrihem, thotë Zoti, do ta vendos dhe do ta tregoj shpëtimin haptazi."},{"t":"sub","x":"Vargu: Fjalët e Zotit janë të dëlira."}]},{"k":"shkurtorja","part":"mengjesore","title":"Shkurtorja","blocks":[{"t":"p","x":"U ngjalle si Perëndi prej varrit me lavdi dhe botën e ngjalle bashkë me veten tënde, dhe natyra e njerëzve të përhimnoi si Perëndi, dhe vdekja humbi, dhe Adami vallëzon, o Kryezot, dhe Eva, tashmë e çliruar prej zinxhirëve, gëzohet duke thirrur: Ti je, o Krisht, ai që u dhuron të gjithëve ngjalljen."}]},{"k":"shtepia","part":"mengjesore","title":"Shtëpia","blocks":[{"t":"p","x":"Le ta përhimnojmë atë që u ngjall pas tri ditësh, si Perëndi të Tërëfuqishëm, që dërrmoi dyert e Hadhit dhe ngriti prej varrit të vdekurit që prej kohësh, iu shfaq miroprurëseve ashtu siç deshi vetë, duke u thënë më parë atyre “Gëzohuni”, dhe apostujve u lajmëroi gëzimin, si i vetmi jetëdhënës. Prandaj gratë, me besim, u ungjillëzojnë nxënësve simbolet e fitores; dhe Hadhi rënkon, dhe vdekja vajton; bota ngazëllohet dhe të gjithë gëzohen së bashku. Se ti, o Krisht, u dhuron të gjithëve ngjalljen."}]},{"k":"lavderimet","part":"mengjesore","title":"Vargëzimet e Lavdërimeve","blocks":[{"t":"p","x":"Himnojmë, o Krisht, pësimin tënd shpëtimtar dhe lavdërojmë ngjalljen tënde."},{"t":"p","x":"O Zot, që durove kryq dhe shfuqizove vdekjen, dhe u ngjalle së vdekurish, paqësonaje jetën, si i vetmi i Tërëfuqishëm."},{"t":"p","x":"O Krisht, që plaçkite Hadhin dhe e ngjalle njeriun me ngjalljen tënde, denjësona të të himnojmë e të të lavdërojmë me zemër të pastër."},{"t":"p","x":"Duke lavdëruar denjimin tënd të perëndishëm, të himnojmë, o Krisht; linde prej Virgjëreshës dhe ishe i pandarë nga Ati; pësove si njeri dhe duke dashur durove kryq, u ngrite prej varrit si prej nusëroreje, që të shpëtosh botën, o Zot, lavdi më ty."},{"t":"p","x":"Kur u mbërtheve mbi drurin e kryqit, atëherë vdiq fuqia e armikut; krijesa u trondit nga frika jote dhe Hadhi u plaçkit nga pushteti yt. Të vdekurit i ngrite nga varret dhe kusarit i çele Parajsën, o Krisht, Perëndia ynë, lavdi më ty."},{"t":"p","x":"Gratë e nderuara, duke vajtuar, erdhën me nxitim te varri yt dhe, si e gjetën varrin të hapur dhe mësuan prej engjëllit çudinë e re dhe të mahnitshme, u lajmëruan apostujve që u ngjall Zoti dhe i dhuroi botës përdëllimin e madh."},{"t":"p","x":"I falemi plagës së hyjshme të pësimeve të tua, o Krisht Perëndi, dhe shërbesës sate të shenjtë zotërore që u krye në Sion dhe që u shfaq nga ti, si Perëndi, në fund të jetëve, se dielli i drejtësisë i ndriti ata që flinin në errësirë, duke i udhëhequr drejt ndriçimit të paperënduar. O Zot, lavdi më ty."},{"t":"p","x":"Dëgjo, o turmë rrëmujëdashëse e judenjve: Ku janë ata që shkuan te Pilati? Le të thonë ushtarët që e ruanin: Ku janë vulat e varrit? Ku u vendos i varrosuri? Ku u shit i pashituri? Si u vodh thesari? Përse shpifni për ngjalljen e të Kryqëzuarit, o judenj të paligjshëm? U ngjall i liri ndër të vdekurit dhe i fal botës përdëllimin e madh."}]}]},{"n":"Tingulli i Dytë","sections":[{"k":"thirrtoret","part":"mbremesore","title":"Vargëzimet e Thirrtoreve","blocks":[{"t":"p","x":"Ejani t’i falemi atij që lindi prej Atit para jetëve, Fjalës Perëndi që u mishërua prej Virgjëreshës Mari. Se, sikundër deshi vetë, pasi duroi kryq, u dorëzua për varrim; dhe si u ngjall së vdekurish, më shpëtoi mua, njeriun e mashtruar."},{"t":"p","x":"Krishti, Shpëtimtari ynë, e fshiu dorëshkrimin që ishte kundër nesh, duke e mbërthyer në Kryq, dhe shfuqizoi pushtetin e vdekjes. I falemi Ngjalljes së tij të triditshme."},{"t":"p","x":"Bashkë me kryeengjëjt le të himnojmë Ngjalljen e Krishtit; se ai është Çliruesi dhe Shpëtimtari i shpirtrave tanë; dhe me lavdi të frikshme dhe me forcë të fuqishme do të vijë përsëri të gjykojë botën që krijoi."},{"t":"p","x":"pyete Dhorin, se kam harruar ta pyes, se duhet zwvendwsuar kjo me tw verdhw"},{"t":"p","x":"Ty që u kryqëzove dhe u varrose, engjëlli të shpalli Kryezot dhe u thoshte grave: Ejani të shikoni ku ndodhej Zoti; se u ngjall sikundër tha, si i Tër’fuqishëm. Prandaj të falemi ty, të vetmit të pavdekshëm, o Krisht Jetëdhënës, mëshirona."},{"t":"p","x":"Mbi Kryqin tënd shfuqizove mallkimin e drurit; me varrimin tënd vrave pushtetin e vdekjes; dhe me Ngjalljen tënde ndriçove gjininë e njerëzve. Prandaj po të thërresim: O Mirëbërës Krisht, Perëndia ynë, lavdi më ty."},{"t":"p","x":"T’u hapën, o Zot, nga frika dyert e vdekjes dhe portarët e Hadhit, kur të panë, u drodhën; se dërrmove dyert prej bronzi dhe theve kyçet e hekurta, dhe na nxore prej errësirës e hijes së vdekjes dhe theve zinxhirët tanë."},{"t":"p","x":"Duke kënduar himnin shpëtimtar, le të ligjërojmë me gojë: Ejani, të gjithë, të biem në gjunjë në shtëpinë e Zotit, duke thënë: Ti që u kryqëzove mbi dru dhe u ngjalle së vdekurish, që je në gjirin e Atit, falna neve mëkatet tona."}]},{"k":"dogmatiku","part":"mbremesore","title":"Hyjlindësorja Dogmatike","blocks":[{"t":"p","x":"Shkoi hija e ligjit, kur erdhi Hiri. Se, sikundër ferra nuk digjej, megjith’se nxirrte flakë, ashtu edhe ti Virgjëreshë linde dhe Virgjëreshë mbete; në vend të kolonës prej zjarri, lindi diell drejtësie; në vend të Moisiut, Krishti, shpëtimi i shpirtrave tanë."}]},{"k":"pasvargjet","part":"mbremesore","title":"Pasvargjet","blocks":[{"t":"p","x":"Ngjallja jote, o Krisht Shpëtimtar, ndriti tërë botën dhe thirre prapë krijesën tënde. Zot i Tërëfuqishëm, lavdi më ty."},{"t":"p","x":"Me anën e drurit, o Shpëtimtar, shfuqizove mallkimin e drurit, me varrimin tënd vrave fuqinë e vdekjes; dhe me Ngjalljen tënde ndrite gjininë tonë. Prandaj po të thërresim: O Jetëdhënës Krisht, Perëndia ynë, lavdi më  ty."},{"t":"p","x":"Duke u shfaqur, o Krisht, i mbërthyer në kryq, ndryshove bukurinë e krijesave; dhe ushtarët, duke treguar çnjerëzi, shpuan brinjën tënde me shtizë; hebrenjtë kërkuan të vulosnin varrin, duke mos njohur pushtetin tënd; por ti, që durove varrim nga zemërgjerësia, u ngjalle pas tri ditësh. O Zot, lavdi më ty."},{"t":"p","x":"O Jetëdhënës Krisht, që durove me dashje pësim për njerëzit, zbrite në Hadh si i fuqishëm dhe si i rrëmbeve prej dorës së të fortit ata që prisnin ardhjen tënde atje, u dhurove Parajsën në vend të Hadhit. Prandaj dhe neve, që lavdërojmë Ngjalljen tënde të triditshme, falna ndjesë mëkatesh dhe përdëllimin e madh."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"sub","x":"Hyjlindësorja"},{"t":"p","x":"O çudi e re përmbi gjithë çuditë e vjetra! Se cili njohu nënë të ketë lindur pa burrë dhe të mbajë në prehër atë që mban tërë krijesën? Është vullnet Perëndie ai që lindi, të cilit, o e Gjith’kulluar, meqë e mbajte në krahët e tu si foshnjë dhe meqenëse ke guxim përpara tij si Nënë, mos pusho së ndërmjetuari për ata që të nderojnë, që të na mëshirojë dhe të shpëtojë shpirtrat tanë."}]},{"k":"perleshorja","part":"mengjesore","title":"Përlëshorja Ngjallësore","blocks":[{"t":"p","x":"Kur zbrite te vdekja ti, o jeta e pavdekshme, atëherë Hadhin e vrave me shkëlqimin e hyjnisë; dhe kur ngrite të vdekurit nga fundet e dheut, gjithë fuqitë qiellore të thërrisnin: Jetëdhënës Krisht, Perëndia ynë, lavdi më ty."}]},{"k":"hyjlindesorja","part":"mengjesore","title":"Hyjlindësorja Ngjallësore","blocks":[{"t":"p","x":"Të gjitha përmbi mendim, të gjitha të përmbilavdishme misteret e tua, o Hyjlindëse; e vulosur me qashtërsi dhe e ruajtur me virgjëri, u njohe Nënë e vërtetë, pasi linde Perëndinë e vërtetë. Atij lutju të shpëtohen shpirtrat tanë."}]},{"k":"ndenjesoret1","part":"mengjesore","title":"Pas Stihologjisë së parë, Ndenjësoret","blocks":[{"t":"p","x":"Bujari Josif, si e zbriti prej drurit trupin tënd të pacenuar, e mbështolli me pëlhurë të pastër dhe me aroma, dhe me vajtime e vuri në një varr të ri; po u ngjalle pas tri ditësh, o Zot, dhe i fale botës përdëllimin e madh."},{"t":"sub","x":"Lavdi"},{"t":"p","x":"Grave miroprurëse, duke qëndruar pranë varrit, engjëlli u thërriste: Mirot u kanë hije të vdekurve, po Krishti u tregua i huaj për prishjen. Thërrisni pra: U ngjall Zoti dhe i fali botës përdëllimin e madh."},{"t":"sub","x":"Tani"},{"t":"p","x":"E Përmbilavdëruar je, o Hyjlindëse Virgjëreshë, të himnojmë, se me anën e kryqit të Birit tënd u mposht Hadhi dhe vdekja vdiq; ne të vdekurit u ngjallën dhe u denjësuam për jetën; morëm Parajsën, kënaqësinë e vjetër. Prandaj, duke falënderuar, e lavdërojmë Krishtin, Perëndinë tonë, të fuqishmin si dhe të vetmin mëshirëplot’."}]},{"k":"ndenjesoret2","part":"mengjesore","title":"Pas Stihologjisë së dytë, Ndenjësoret","blocks":[{"t":"p","x":"Duke mos ndaluar të vuloset guri i varrit, u fale të gjithëve shkëmbin e besës, pasi u ngjalle. O Zot, lavdi më ty."},{"t":"sub","x":"Lavdi"},{"t":"p","x":"Shoqëria e nxënësve të tu bashkë me gratë miroprurëse gëzohen njëzëri, se me ta kremtojmë një të kremte të përbashkët për lavdi dhe nder të Ngjalljes sate. Me anën e tyre, Zot njeridashës, fali popullit tënd përdëllimin e madh."},{"t":"sub","x":"Tani"},{"t":"p","x":"E Përmbibekuar je, o Hyjlindëse Virgjëreshë, se me anën e atij që u mishërua prej teje Hadhi u robërua, Adami u rithirr, mallkimi vdiq, Eva u çlirua, vdekja vdiq, dhe ne morëm jetën; prandaj, duke përhimnuar, thërresim: I bekuar je, o Krisht, Perëndia yn’, që të pëlqeu kështu, lavdi më ty."}]},{"k":"degjimi","part":"mengjesore","title":"Dëgjimi","blocks":[{"t":"p","x":"Kur shkuan gratë te varri pas pësimit, për të mirosur trupin tënd, o Krisht Perëndi, panë engjëj në varr dhe u çuditën, se prej tyre dëgjuan një zë që u ngjall Zoti, duke i dhuruar botës përdëllimin e madh."}]},{"k":"shkallesat","part":"mengjesore","title":"Shkallesat","blocks":[{"t":"sub","x":"Antifoni i parë"},{"t":"p","x":"Syt’ e zemrës sime i ngre në qiell te ti, o Shpëtimtar; shpëtomë me ndriçimin tënd."},{"t":"p","x":"Mëshirona ne që mëkatojmë shumë çdo orë, o Zoti Krisht, dhe jepna përpara fundit mënyra që të pendohemi para teje."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Shpirti i Shenjtë ka fuqi të mbretërojë, të shenjtërojë dhe të lëvizë krijesën, se është Perëndi i bashkëqenshëm me Atin e me Fjalën."},{"t":"sub","x":"Antifoni i dytë"},{"t":"p","x":"Po të mos ishte Zoti me ne, cili do të ishte i aftë të ruhej i pangarë prej armikut dhe njerivrasësit?"},{"t":"p","x":"Mos e dorëzo, o Shpëtimtar, në dhëmbët e tyre shërbëtorin tënd, se armiqtë e mi vërsulen kundër meje si luanë."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Shpirti i Shenjtë është burim jete dhe lavdie, se, duke qenë Perëndi, i forcon dhe i ruan të gjitha të krijuarat më Atin me anën e Birit."},{"t":"sub","x":"Antifoni i tretë"},{"t":"p","x":"Ata që kanë besim te Zoti, i shëmbëllejnë malit të shenjtë; këta nuk tronditen fare nga goditjet e Beliarit."},{"t":"p","x":"Ata që bëjnë jetë hyjnore, le të mos i zgjatin duart në paudhësi, se Krishti nuk do ta lërë shkopin e mëkatarëve të bjerë mbi trashëgimin e tij."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Prej Shpirtit të Shenjtë buron çdo urtësi, dhe prej tij marrin Hir apostujt, dhe dëshmorët kurorëzohen në ndeshje, dhe profetët shohin."}]},{"k":"paravargu","part":"mengjesore","title":"Paravargu","blocks":[{"t":"p","x":"Ngrihu, o Zot, o Perëndia im, sipas urdhrit që dhé dhe mbledhja e popujve do të të rrethojë."},{"t":"sub","x":"Vargu: O Zot, Perëndia im, më ty shpresova."}]},{"k":"shkurtorja","part":"mengjesore","title":"Shkurtorja","blocks":[{"t":"p","x":"U ngjalle prej varrit, o Shpëtimtar i Tërëfuqishëm, dhe Hadhi u habit kur pa këtë çudi, dhe të vdekurit ngjalleshin, dhe krijesa, kur pa, gëzohej bashkë me ty, dhe Adami ngazëllohet dhe bota, o Shpëtimtari im, të himnon përherë."}]},{"k":"shtepia","part":"mengjesore","title":"Shtëpia","blocks":[{"t":"p","x":"Ti je drita e të errësuarve, ti je ngjallja e të gjithëve dhe jeta e njerëzve, dhe të gjithë bashkë i ngjalle, pasi plaçkite pushtetin e vdekjes, o Shpëtimtar, dhe pasi dërrmove dyert e Hadhit, o Fjalë. Dhe njerëzit u habitën kur panë këtë çudi, dhe tërë krijesa së bashku gëzohet për Ngjalljen tënde, o Njeridashës. Prandaj të gjithë lavdërojmë dhe himnojmë denjimin tënd, dhe bota, o Shpëtimtari im, të himnon përherë."}]},{"k":"lavderimet","part":"mengjesore","title":"Vargëzimet e Lavdërimeve","blocks":[{"t":"p","x":"Çdo frymë dhe çdo krijesë ty të lavdëron, o Zot, se me anën e Kryqit shkatërrove vdekjen, që t’u tregosh popujve Ngjalljen tënde prej së vdekurish, si i vetmi njeridashës."},{"t":"p","x":"Le të thonë judenjtë: Si e humbën ushtarët kur e ruanin Mbretin? Përse guri nuk e ruajti gurin e jetës? Ose të japin të varrosurin, ose t’i falen të ngjallurit, duke thënë bashkë me ne: Lavdi shumicës së dhembshurive të tua, o Shpëtimtari ynë, lavdi më ty."},{"t":"p","x":"Gëzohuni, popuj, dhe ngazëllohuni; engjëlli ndenji mbi gurin e varrit; ai na ungjillëzoi duke thënë: Krishti u ngjall prej së vdekurish, Shpëtimtari i botës, dhe i mbushi të gjitha me erë lulesh. Gëzohuni, popuj, dhe ngazëllohuni."},{"t":"p","x":"Engjëlli, o Zot, i solli Hirplotes përshëndetjen “gëzohu” para zënies sate; engjëlli rrokullisi dhe gurin e varrit tënd të lavdëruar me ngjalljen tënde. Njëri duke lajmëruar simbole ngazëllimi në vend të helmit; tjetri duke na lëçitur Zotin Jetëdhënës në vend të vdekjes. Prandaj po të thërresim: O Zot, mirëbërës i të gjithëve, lavdi më ty."},{"t":"p","x":"Gratë spërkatën me miro dhe lot varrin tënd, dhe goja e tyre u mbush plot me gëzim kur thoshin: U ngjall Zoti."},{"t":"p","x":"Kombe dhe popuj le të lavdërojnë Krishtin, Perëndinë tonë, i cili duroi kryq për ne vullnetarisht, dhe qëndroi tri ditë në Hadh, dhe le t’i falen Ngjalljes së tij prej së vdekurish, me anën e së cilës u ndriçuan gjithë skajet e botës."},{"t":"p","x":"U kryqëzove, u varrose, o Krisht, siç deshe plaçkite vdekjen, si Perëndi dhe Zot, edhe i dhurove botës jetën e amshuar dhe përdëllimin e madh."},{"t":"p","x":"O të paligjshëm me të vërtetë, duke vulosur varrin, na denjësuat për një çudi më të madhe; e dinë ruajtësit: sot doli prej varrit, dhe u thoshin: Thoni se, kur po flinim ne, erdhën dishepujt dhe e vodhën. Por kush vjedh një të vdekur dhe për më tepër të zhveshur? Ai u ngjall me fuqinë e tij si Perëndi, duke lënë në varr dhe pëlhurat e tij. Ejani, shikoni, o judenj, se si nuk i theu vulat ai që shkeli vdekjen dhe i dhuroi gjinisë së njerëzve jetën e pasosur dhe përdëllimin e madh."}]}]},{"n":"Tingulli i Tretë","sections":[{"k":"thirrtoret","part":"mbremesore","title":"Vargëzimet e Thirrtoreve","blocks":[{"t":"p","x":"Me anën e Kryqit tënd, o Krisht Shpëtimtar, u shpërbë pushteti i vdekjes dhe mashtrimi i djallit u shfuqizua. Dhe gjinia e njerëzve që shpëtohet me besë, himne përditë të blaton."},{"t":"p","x":"U ndriçuan të gjitha me Ngjalljen tënde, o Zot. Parajsa u hap përsëri; dhe tërë krijesa, duke të lavdëruar, himne përditë të blaton."},{"t":"p","x":"Lavdëroj fuqin’ e Atit e të Birit dhe himnoj pushtetin e Shpirtit të Shenjtë, Hyjninë e pandarë dhe të pakrijuar, Trinin’ e bashkëqenshme, që mbretëron në jetë të jetës."},{"t":"p","x":"Kryqit tënd të çmuar i falemi, o Krisht, dhe Ngjalljen tënde himnojmë dhe lavdërojmë; se me plagën tënde ne të gjithë u shëruam."},{"t":"p","x":"Himnojmë Shpëtimtarin që u mishërua prej Virgjëreshës, se u kryqëzua për ne dhe u ngjall në ditën e tretë, duke na dhuruar përdëllimin e madh."},{"t":"p","x":"Krishti zbriti dhe u ungjillëzoi atyre që ishin në Hadh, duke thënë: Kini kurajë, tani kam fituar. Unë jam Ngjallja. Unë do t’ju ngre lart duke thyer dyert e vdekjes."},{"t":"p","x":"Ne të pavyerit që qëndrojmë në shtëpinë tënde të pacenuar, këndojmë himne mbrëmësore, duke thirrur thellësisht: O Krisht Perëndi, që ndriçove botën me Ngjalljen tënde të triditshme, shpëto popullin nga dora e armiqve të tu, o Njeridashës."}]},{"k":"dogmatiku","part":"mbremesore","title":"Hyjlindësorja Dogmatike","blocks":[{"t":"p","x":"Si të mos admirojmë lindjen tënde hyjnjerëzore, o e Gjithënderuar? Se, pa njohur burrë, o e Gjithëkulluar, linde Bir pa Atë trupërisht atë që lindi prej Atit para jetëve pa nënë, i cili s’pësoi fare ndryshim, as përzierje, as ndarje, por ruajti të plotë cilësinë e secilës natyrë. Prandaj, o Zonjë, Nënë Virgjëreshë, atij lutju që të shpëtohen shpirtrat e atyre që me besim të drejtë të njohin si Hyjlindëse."}]},{"k":"pasvargjet","part":"mbremesore","title":"Pasvargjet","blocks":[{"t":"p","x":"O Krisht, që errësove diellin me pësimin tënd dhe ngazëllove gjithësinë me dritën e Ngjalljes sate, prit himnin tonë mbrëmësor, o Njeridashës."},{"t":"p","x":"Ngjallja jote jetëdhënëse, o Zot, ndriçoi tërë botën dhe rithirri krijesën e vet që u prish. Prandaj, të çliruar prej mallkimit të Adamit, thërresim: O Zot i Tër’fuqishëm, lavdi më ty."},{"t":"p","x":"Duke qenë Perëndi i pandryshuar, pësove ndryshim duke vuajtur trupërisht; por krijesa, duke mos duruar të të shikonte të varur, tronditej nga frika dhe, duke rënkuar, himnonte zemërgjerësinë tënde; dhe si zbrite në Hadh, u ngjalle pas tri ditësh, dhe i dhurove botës jetën dhe përdëllimin e madh."},{"t":"p","x":"Që të çlirosh gjininë tonë prej vdekjes, o Krisht, durove vdekje; dhe si u ngjalle së vdekurish pas tri ditësh, bashkëngjalle me veten tënde ata që të njohën si Perëndi, dhe botën e ndrite, o Zot, lavdi më ty."},{"t":"sub","x":"Lavdi dhe tani"},{"t":"sub","x":"Hyjlindësorja"},{"t":"p","x":"Pa farë prej Shpirtit të Shenjtë, sipas vullnetit të Atit, zure të Birin e Perëndisë, që lindi prej Atit pa nënë para jetëve, e linde për ne trupërisht pa Atë dhe e rrite si foshnjë. Prandaj mos resht së ndërmjetuari që të shpëtohen shpirtrat tanë prej rreziqeve."}]},{"k":"perleshorja","part":"mengjesore","title":"Përlëshorja Ngjallësore","blocks":[{"t":"p","x":"Le të dëfrejnë qielloret, le të ngazëllohen të dheshmet, se rrëfeu fuqi me krahun e tij, Zoti shkeli vdekjen me vdekje; u bë i parëlindur i të vdekurve; prej barkut të Hadhit neve na çliroi, dhe i fali botës përdëllimin e madh."}]},{"k":"hyjlindesorja","part":"mengjesore","title":"Hyjlindësorja Ngjallësore","blocks":[{"t":"p","x":"Ty që ndërmjetove për shpëtimin e gjinisë sonë, të përhimnojmë, o Hyjlindëse Virgjëreshë, se, duke denjuar pësimin e Kryqit me trupin që mori prej teje, Biri yt dhe Perëndia ynë na çliroi prej prishjes si Njeridashës."}]},{"k":"ndenjesoret1","part":"mengjesore","title":"Pas Stihologjisë së parë, Ndenjësoret","blocks":[{"t":"p","x":"Krishti u ngjall së vdekurish, si i pari i të fjeturve; i parëlinduri i krijesës dhe Krijues i gjithë gjërave, përtëriti në veten e tij natyrën e prishur të gjinisë sonë. Nuk zotëron më, o vdekje, se Zoti i të gjithave e dërrmoi pushtetin tënd."},{"t":"sub","x":"Lavdi"},{"t":"p","x":"Si shijove vdekjen trupërisht, o Zot, pushove hidhërimin e vdekjes me Ngjalljen tënde, dhe e forcove njeriun kundër saj, duke shpallur disfatën e mallkimit të vjetër. O Zot, mbrojtës i jetës sonë, lavdi më ty."},{"t":"sub","x":"Tani"},{"t":"p","x":"Për bukurinë e virgjërisë sate e për shkëlqimin e qashtërisë sate, Gabrieli u çudit, o Hyjlindëse, dhe të thërriste: Çfarë lëvdate të të sjell të vyershme? Dhe si të të quaj, nuk e di e po shtangem. Prandaj të thërres si u urdhërova: Gëzohu, o Hirplote."},{"t":"sub","x":"Tjetër"},{"t":"sub","x":"Tin oreotita"},{"t":"p","x":"O bukuri me nam, o virgjëri pa cen, o drit’ e diellit, o hën’ e qiellit, shën Gabrieli kur të pa, çuditej dhe të thërriste: Si të të lavdëroj, o Mari, o Hyjlindëse? Ç’këngë të këndoj për ty? Nuk e di dhe kërkoj më kot. Pra, them sikundër jam porositur: Gëzohu, Virgjëreshë hirplote."}]},{"k":"ndenjesoret2","part":"mengjesore","title":"Pas Stihologjisë së dytë, Ndenjësoret","blocks":[{"t":"sub","x":"Tin oreotita"},{"t":"p","x":"Të papësuarin si një njeri mbi kryq, të pandryshuarin midis të vdekurve, Hadhi e pa dhe u çudit dhe qante me vaj dhe zi. Dridhem ngaqë trupi i tij as u tret, as u prish aspak, vetë Zotin kam në gji, më lufton i padukuri. Të gjith’ të vdekurit thërresin: Nder dhe lavdi më ty, o Zoti Krisht."},{"t":"sub","x":"Lavdi"},{"t":"sub","x":"Tin oreotita"},{"t":"p","x":"Nuk e kuptojmë dot çudin’ e Kryqit tënd, nuk e shpjegojmë dot Ngjalljen e ndritshme, dhe i nxonitim besërisht misteret e habitshme. Vdekja u përmbys përdhe edhe Hadhi sot u plaçkit, gjinia njerëzore pra, me paprishjen tani u vesh. Të gjithë pra thërresim me zë të madh: Nder dhe lavdi më ty, o Zoti Krisht."},{"t":"sub","x":"Tani"},{"t":"sub","x":"Tin oreotita"},{"t":"p","x":"Të pakuptuarin, të papërshkruarin, të bashkëqenshmin, Birin dhe Perëndinë, në gjirin tënd mistikërisht e nxure, o Virgjëreshë. Pamë pra një veprim të Trinisë plot me lavdi, kur e linde Zotin Krisht, Nën’ e shenjtë Hyjlindëse. Të gjithë pra thërresim me zë të madh: Gëzohu, Virgjëreshë Hirplote."}]},{"k":"degjimi","part":"mengjesore","title":"Dëgjimi","blocks":[{"t":"p","x":"I çuditshëm nga pamja dhe me fjalë plot freski, engjëlli i ndritshëm u thoshte miroprurëseve: Si e kërkoni të gjallin në varr? U ngjall, duke zbrazur varret. Njihni të pandryshuarin, si ndryshues të prishjes. Thojini Perëndisë: Sa të frikshme janë veprat e tua! Se ti e shpëtove gjininë e njerëzve."}]},{"k":"shkallesat","part":"mengjesore","title":"Shkallesat","blocks":[{"t":"sub","x":"Antifoni i parë"},{"t":"p","x":"Robërinë e Sionit ti e nxore prej Babilonës, dhe mua hiqmë prej pësimeve drejt jetës, o Fjalë."},{"t":"p","x":"Ata që mbjellin në jug me lot të hyjshëm, do të korrin kallinj në gëzimin e jetës së amshuar."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Prej Shpirtit të Shenjtë vjen çdo dhurat’ e mirë, i cili shkëlqen me Atin e me Birin, dhe me të cilin të gjitha rrojnë dhe lëvizin."},{"t":"sub","x":"Antifoni i dytë"},{"t":"p","x":"Në mos e ndërtoftë Zoti shtëpinë e virtyteve, më kot mundohemi. Po të na e mbrojë shpirtin ai, asnjë s’na e zapton qytetin."},{"t":"p","x":"Shenjtorët janë të tutë përherë, si dhe të Atit, o Krisht, që linde prej barkut si Bir me anën e Shpirtit të Shenjtë."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Te Shpirti i Shenjtë duket çdo shenjtëri dhe urtësi, se qenëson tër’ krijesën. Atë e adhurojmë, se është Perëndi, si Atin e Birin."},{"t":"sub","x":"Antifoni i tretë"},{"t":"p","x":"Lum ata që i kanë frikë Zotit, do të ecin në rrugët e porosive, se do të hanë nga gjith’ frutat e jetës."},{"t":"p","x":"Dëfre, o kryebari, duke parë rreth tryezës sate nipërit e tu që sjellin degë veprash të mira."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"E Shpirtit të Shenjtë është gjithë pasuria e lavdisë, dhe prej tij rrjedh hir dhe jetë për tër’ krijesën, se përhimnohet bashk’ me Atin e me Fjalën."}]},{"k":"paravargu","part":"mengjesore","title":"Paravargu","blocks":[{"t":"p","x":"Thojuni kombeve, se Zoti mbretëroi, se e siguroi tërë botën, e cila nuk do të tundet."},{"t":"sub","x":"Vargu: Këndojini Zotit këngë të re."}]},{"k":"shkurtorja","part":"mengjesore","title":"Shkurtorja","blocks":[{"t":"p","x":"U ngjalle sot prej varrit, o Zemërdhembshur, edhe na nxore nga dyert e vdekjes. Sot Adami vallëzon dhe Eva gëzohet. Bashkë me ta profetët dhe patriarkët përhimnojnë pareshtur pushtetin e hyjshëm të fuqisë sate."}]},{"k":"shtepia","part":"mengjesore","title":"Shtëpia","blocks":[{"t":"p","x":"Qielli e toka le të vallëzojnë sot, dhe Krishtin Perëndi njëzëri le ta himnojnë, se i ngriti robërit prej varreve. E gjithë krijesa gëzohet, duke i ofruar këngë të denja Krijuesit të gjithësisë dhe Çliruesit tonë; se, duke nxjerrë sot njerëzit prej Hadhit si Jetëdhënës, i lartëson ata drejt qiellit, dhe dërrmon kryelartësinë e armikut, dhe thyen dyert e Hadhit me pushtetin e hyjshëm të fuqisë së tij."}]},{"k":"lavderimet","part":"mengjesore","title":"Vargëzimet e Lavdërimeve","blocks":[{"t":"p","x":"Ejani, gjithë kombet, njihni fuqinë e misterit të frikshëm, se Krishti, Shpëtimtari yn’, Fjala e kryes, u kryqëzua për ne dhe, duke dashur, u varros, dhe u ngjall së vdekurish, që t’i shpëtojë të gjitha; atij le t’i falemi."},{"t":"p","x":"I rrëfyen gjith’ çuditë e tua ruajtësit e tu, o Zot, po këshilli i kotësisë, si mbushi me dhurata të djathtën e tyre, pandehte se fshihte Ngjalljen tënde që e lavdëron bota; mëshirona."},{"t":"p","x":"Të gjitha u mbushën me gëzim kur morën lajmin e Ngjalljes. Maria Magdalena erdhi në varr, gjeti një engjëll që rrinte mbi gur, që i shkëlqenin rrobat dhe i tha: Si kërkoni të gjallin ndër të vdekurit? S’është këtu, por u ngrit siç tha, dhe ju pret në Galile."},{"t":"p","x":"Në dritën tënde, o Zot, do të shikojmë dritë, o Njeridashës, që u ngjalle së vdekurish, duke i dhuruar shpëtim gjinisë së njerëzve, që të të lavdërojë tërë krijesa ty, të vetmin të pamëkatshëm; mëshirona."},{"t":"p","x":"Gratë miroprurëse blatuan lot si himne mëngjesore, o Zot; se, duke mbajtur aroma me er’ të mirë, zunë varrin tënd, duke shpejtuar të mirosnin Trupin tënd të pacenuar. Engjëlli që rrinte mbi gur, i ungjillëzoi: Si kërkoni të gjallin ndër të vdekurit? Se, duke shkelur vdekjen, u ngjall si Perëndi dhe u fali të gjithëve përdëllimin e madh."},{"t":"p","x":"Një engjëll që vetëtinte mbi varrin tënd jetëbërës, u thoshte miroprurëseve: I zbrazi varret Çliruesi, plaçkiti Hadhin dhe u ngjall pas tri ditësh, si i vetmi Perëndi i Tër’fuqishëm."},{"t":"p","x":"Erdhi në varr e të kërkoi ditën e parë të javës Maria Magdalena; dhe, duke mos të gjetur, vajtonte duke thirrur me lot: Mjerë unë, o Shpëtimtari im! Si të vodhën, o Mbret i të gjithëve? Por dy engjëj jetëprurës thërrisnin nga brenda varrit: Përse qan, o grua? Qaj, thotë, se ma ngritën Zotin prej varrit dhe nuk di ku e vunë. Por, kur u kthye mbrapa e të pa, të thërriti menjëherë: Zoti im dhe Perëndia im, lavdi më ty."},{"t":"p","x":"Hebrenjtë e mbyllën jetën në varr, por kusari çeli Parajsën me gojën e tij, duke thirrur dhe duke thënë: Ai që u kryqëzua me mua për mua, varej bashk’ me mua mbi dru dhe më dukej që rrinte mbi fron bashkë me Atin. Se ai është Krishti, Perëndia ynë, që ka përdëllimin e madh."}]}]},{"n":"Tingulli i Katërt","sections":[{"k":"thirrtoret","part":"mbremesore","title":"Vargëzimet e Thirrtoreve","blocks":[{"t":"p","x":"Duke iu falur Kryqit tënd jetëdhënës pa pushim, o Krisht Perëndi, lavdërojmë Ngjalljen tënde të triditshme; se me të përtërite natyrën e prishur të njerëzve, o i Tër’fuqishëm, dhe na tregove ngjitjen në qiej, si i vetmi i mirë dhe njeridashës."},{"t":"p","x":"Mallkimin e drurit të mosbindjes e zgjidhe, o Shpëtimtar, duke u mbërthyer vullnetarisht mbi drurin e Kryqit; dhe duke zbritur në Hadh, o i Fortë, dërrmove zinxhirët e vdekjes si Perëndi. Prandaj i falemi Ngjalljes sate prej së vdekurish, duke thirrur me ngazëllim: O Zot i Tër’fuqishëm, lavdi më ty."},{"t":"p","x":"I dërrmove dyert e Hadhit, o Zot, dhe me vdekjen tënde shkatërrove mbretërinë e vdekjes, ndërsa gjininë e njerëzve e çlirove prej prishjes, duke i dhuruar botës jetën dhe paprishjen, dhe përdëllimin e madh."},{"t":"p","x":"Ejani të përhimnojmë, o popuj, Ngritjen e triditshme të Shpëtimtarit, me anën e së cilës u çliruam nga zinxhirët e pazgjidhur të Hadhit, dhe morëm të gjithë jetën dhe paprishjen, duke thirrur: Ti që u kryqëzove e u varrose dhe u ngjalle, shpëtona me Ngjalljen tënde, o i vetmi Njeridashës."},{"t":"p","x":"Engjëj dhe njerëz, o Shpëtimtar, himnojnë Ngjalljen tënde të triditshme, me anën e së cilës u ndriçuan skajet e botës dhe u çliruam prej robërisë së armikut gjith’ ne që thërresim: O Jetëbërës, Shpëtimtar i Tër’fuqishëm, shpëtona me Ngjalljen tënde, o i vetmi Njeridashës."},{"t":"p","x":"Dërrmove dyert prej bronzi dhe theve kyçet, o Krisht Perëndi, dhe ngjalle gjininë e rënë të njerëzve. Prandaj me një zë po të thërresim: O Zot që u ngjalle së vdekurish, lavdi më ty."},{"t":"p","x":"O Zot, lindja jote prej Atit është pa kohë dhe e amshuar; mishërimi prej Virgjëreshës, i pashprehur dhe i pashpjegueshëm për njerëzit, dhe zbritja në Skëterrë, e frikshme për djallin dhe për engjëjt e tij; se, duke shkelur vdekjen, u ngjalle pas tri ditësh, dhe u fale njerëzve paprishjen dhe përdëllimin e madh."}]},{"k":"dogmatiku","part":"mbremesore","title":"Hyjlindësorja Dogmatike","blocks":[{"t":"p","x":"Profeti David, që prej teje u bë Hyjprind, i parafoli për ty me melodi këngësh atij që bëri gjëra të mëdha te ti: qëndroi Mbretëresha në të djathtën tënde. Se Perëndia, që pëlqeu të bëhet njeri prej teje pa Atë, të shpalli ty Nënë, burim jete, që t’i japë formë sërish ikonës së tij, të prishur prej pasioneve, dhe duke e gjetur delen e arratisur ndër male dhe duke e marrë mbi supe, që pra t’ia sjellë Atit, dhe me dëshirën e tij ta bashkojë atë me Fuqitë qiellore dhe të shpëtojë botën, o Hyjlindëse, Krishti që ka përdëllimin e madh e të pasur."}]},{"k":"pasvargjet","part":"mbremesore","title":"Pasvargjet","blocks":[{"t":"p","x":"O Zot, duke u ngjitur në Kryq, shove mallkimin tonë stërgjyshëror dhe, duke zbritur në Skëterrë, çlirove robërit ndër shekuj dhe i dhurove gjinisë së njerëzve paprishjen. Prandaj, duke himnuar, lavdërojmë Ngjalljen tënde jetëbërëse dhe shpëtimtare."},{"t":"p","x":"I varur mbi dru, i vetmi i Fortë, trondite tërë krijesën; dhe, kur u vure në varr, ngjalle ata që banonin në varre dhe i dhurove gjinisë së njerëzve paprishjen dhe jetën. Prandaj, duke himnuar, lavdërojmë Ngjalljen tënde të triditshme."},{"t":"p","x":"Populli i paligjshëm, o Krisht, të tradhtoi te Pilati dhe të dënoi me kryqëzim, duke u shfaqur mosmir’njohës ndaj Mirëbërësit. Po ti, duke dashur, durove varrim, dhe me vet’ fuqinë tënde u ngjalle pas tri ditësh si Perëndi, dhe na dhurove jetën e amshuar dhe përdëllimin e madh."},{"t":"p","x":"Gratë me lot zunë varrin tënd dhe të kërkonin; dhe, duke mos të gjetur, vajtonin e thoshin duke thirrur me lot: Mjerë ne! O Shpëtimtari ynë dhe Mbret i të gjithëve, si të vodhën? Dhe cili vend e mban trupin tënd jetëprurës? Dhe engjëlli iu përgjigj atyre: Mos qani, thotë, po shkoni e lëçitni që u ngjall Zoti dhe na fali ngazëllimin, si i vetmi i mëshirshëm."},{"t":"sub","x":"Lavdi dhe tani"},{"t":"sub","x":"Hyjlindësorja"},{"t":"p","x":"Priti lutjet e shërbëtorëve të tu, o e Panjollshme, duke pushuar kryengritjet e mjerimeve tona, duke na shpëtuar nga çdo hidhërim; se vetëm ty të kemi spirancë të fortë e të sigurt, dhe kemi mbrojtjen tënde. Mos u turpërofshim, o Zonjë, duke t’u lutur. Shpejto të dëgjosh lutjet e atyre që të thërresin besërisht: Gëzohu, o Zonjë, ndihma e të gjithëve, gëzimi, mbrojtja dhe shpëtimi i shpirtrave tanë."}]},{"k":"perleshorja","part":"mengjesore","title":"Përlëshorja Ngjallësore","blocks":[{"t":"p","x":"Lëçitjen gazmore të Ngjalljes kur e mësuan prej engjëllit, nxënëset e Zotit e hodhën dënimin prindëror, duke u mburrur u thoshin apostujve: U kusarua vdekja, u ngrit Krishti Perëndi dhe i dhuroi botës përdëllimin e madh."}]},{"k":"hyjlindesorja","part":"mengjesore","title":"Hyjlindësorja Ngjallësore","blocks":[{"t":"p","x":"Misteri i fshehur prej jete dhe i panjohur ndër engjëj, u shfaq ndër të dheshmit me anën tënde, o Hyjlindëse, Perëndia që u mishërua me bashkim të papërzier, dhe denjoi kryq për ne duke dashur, me të cilin ngjalli të parëgatuarin dhe shpëtoi prej vdekjes shpirtrat tanë."}]},{"k":"ndenjesoret1","part":"mengjesore","title":"Pas Stihologjisë së parë, Ndenjësoret","blocks":[{"t":"p","x":"Duke parë hyrjen e varrit dhe duke mos duruar flakën e engjëllit, miroprurëset çuditeshin me tmerr duke thënë: Mos u vodh vallë ai që i çeli kusarit Parajsën? Mos u ngjall vallë ai që lëçiti Ngjalljen dhe para pësimit? Me të vërtetë u ngjall Krishti Perëndi, dhe u fali atyre që ishin në Hadh jetën dhe ngjalljen."},{"t":"sub","x":"Lavdi"},{"t":"sub","x":"Kateplagji Josif"},{"t":"p","x":"Deshe vetë, Shpëtimtar, edhe durove kryq për ne, edhe në një varr të ri, njerëz të vunë si njeri, ty që me fjalë themelove anët e dheut. Prandaj u zu si rob vdekja, e huaj për të gjith’, edhe tmerrësisht u plaçkit edhe u vodh, si dhe të gjith’ në Hadh i thërrisnin Ngjalljes sate jetëprurëse. Se Zoti Krisht u ngjall, Jetëprurësi që mbetet përjetë."},{"t":"sub","x":"Tani"},{"t":"sub","x":"Kateplagji Josif"},{"t":"p","x":"Shën Josifi u habit, të përmbinatyrshmen kur e pa, atëherë merrte vesh atë vesën përmbi lëmsh, për zënien tënde të pafarshme, o Hyjlindëse; ferrën që në zjarr dhe që s’digjej dot, shkopin e Aaronit që lulëzoi, edhe dëshmoi Vlesori dhe ruajtësi yt dhe priftërinjve u thoshte: Lind Virgjëresha që, dhe pas lindjes, mbetet prapë e virgjër."}]},{"k":"ndenjesoret2","part":"mengjesore","title":"Pas Stihologjisë së dytë, Ndenjësoret","blocks":[{"t":"sub","x":"Tahi Prokatalave"},{"t":"p","x":"U ngjalle si i Pavdekshëm prej Skëterrës, o Shpëtimtar, dhe botën e tënde ngjalle bashk’ me Ngjalljen tënde mbi dhé, o Krisht, Perëndia yn’; theve me forcën tënde gjith’ pushtetin e vdekjes, shfaqe, o Përdëllyes, te gjith’ njerëzit Ngjalljen. Prandaj të lavdërojmë sot ty, Njeridashësin."},{"t":"sub","x":"Lavdi"},{"t":"sub","x":"Kateplagji Josif"},{"t":"p","x":"Ja së larti zbriti sot engjëll’ i shenjtë Gabriel, dhe si ndenji përmbi gur, atje mbi gurin jetësor, dhe u thërriste atyre që po qanin: Pushojeni, o gra, klithmën tuaj plot vajtim, edhe pse ndieni tani mjaft keqardhje për të; po kini, o gra, kurajë se ai që kërkoni, u ngjall vërtet. Prandaj thërrisni të gjith’ apostujt, se Zoti u ngjall prej së vdekurish."},{"t":"sub","x":"Tani"},{"t":"sub","x":"Kaplagji Josif"},{"t":"p","x":"U çuditën, o Mari, koret e engjëjve me ty, se mister’ i frikshëm ësht’ kjo zënia jote për çudi, se si ai që përmban të gjitha me një fjalë, përmbahet si njeri te pëqiri yt, dhe nisje nga ti pret i Parëjetshmi, edhe thëthin si foshnjë ai që ushqen gjithësinë; dhe ty të gjithë të lavdërojnë, Nën’ e Virgjër Hyjlindëse."}]},{"k":"degjimi","part":"mengjesore","title":"Dëgjimi","blocks":[{"t":"p","x":"Miroprurëset rendën të parat dhe u lëçitnin apostujve për Ngritjen tënde të mahnitshme,  o Krisht, se u ngjalle si Perëndi dhe i fale botës përdëllimin e madh."}]},{"k":"shkallesat","part":"mengjesore","title":"Shkallesat","blocks":[{"t":"sub","x":"Antifoni i parë"},{"t":"p","x":"Që prej rinisë sime shumë pasione më luftojnë, por ti përkrahmë dhe shpëtomë, o Shpëtimtari im."},{"t":"p","x":"Ju që urreni Sionin, kini turp nga Zoti, se do të thaheni si bari prej zjarrit."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Me anën e Shpirtit të Shenjtë merr jetë çdo shpirt, dhe me pastrim lartësohet dhe mistikërisht ndriçohet prej Njësisë Trinisore."},{"t":"sub","x":"Antifoni i dytë"},{"t":"p","x":"Të thirra nxehtësisht, o Zot, nga thellësia e shpirtit tim; më dëgjofshin veshët e tu të hyjshëm."},{"t":"p","x":"Cilido që ka gjithë shpresën te Zoti, ësht’ më lart nga gjith’ të hidhëruarit."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Me anën e Shpirtit të Shenjtë rrjedhin burimet e Hirit, që vaditin tërë krijesën për rilindje jete."},{"t":"sub","x":"Antifoni i tretë"},{"t":"p","x":"Zemra ime le të ngrihet te ti, o Fjalë, dhe atëherë asnjë nga gjërat e pëlqyeshme të botës nuk do të më tërheqë që t’i kem zili."},{"t":"p","x":"Zotit i detyrojmë dashuri më të nxehtë se ajo që ka njeriu për nënën e tij."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Te Shpirti i Shenjtë është pasuria e hyjdijes, e soditjes dhe e urtësisë, se atij ia zbulon Fjala gjith’ doktrinat atërore."}]},{"k":"paravargu","part":"mengjesore","title":"Paravargu","blocks":[{"t":"p","x":"Ngrihu, o Zot, ndihmona dhe çlirona për lavdi të emrit tënd."},{"t":"sub","x":"Vargu: O Perëndi, dëgjuam me veshët tanë."}]},{"k":"shkurtorja","part":"mengjesore","title":"Shkurtorja","blocks":[{"t":"p","x":"Shpëtimtari dhe Çlirimtari im ngjalli prej varrit si Perëndi njerëzit e robëruar dhe dërrmoi dyert e Hadhit dhe si Kryezot u ngjall pas tri ditësh."}]},{"k":"shtepia","part":"mengjesore","title":"Shtëpia","blocks":[{"t":"p","x":"Krishtin jetëdhënës që u ngjall prej së vdekurish prej varrit pas tri ditësh dhe dërrmoi sot dyert e vdekjes me fuqinë e tij, që vrau Hadhin dhe e hoqi gjembin e vdekjes, dhe që e çliroi Adamin me Evën, le ta himnojmë të gjithë ne njerëzit, duke thirrur nxehtësisht me falënderim një lavdërim: Se ai, si i vetmi Perëndi i fortë dhe si Kryezot, u ngjall pas tri ditësh."}]},{"k":"lavderimet","part":"mengjesore","title":"Vargëzimet e Lavdërimeve","blocks":[{"t":"p","x":"O Zot i tër’fuqishëm, që durove kryq e vdekje dhe u ngjalle së vdekurish, lavdërojmë Ngjalljen tënde."},{"t":"p","x":"Me Kryqin tënd, o Krisht, na çlirove prej mallkimit të moçëm, dhe me vdekjen tënde shkatërrove djallin që tiranizoi natyrën ton’, dhe me Ngjalljen tënde i mbushe të gjitha me gaz. Prandaj po të thërresim: O Zot, që u ngjalle së vdekurish, lavdi më ty."},{"t":"p","x":"Me Kryqin tënd, o Krisht Shpëtimtar, udhëhiqna në të vërtetën tënde dhe shpëtona nga grackat e armikut. Ti që u ngjalle së vdekurish, ngjallna ne që ramë nga mëkati, duke nderë dorën tënde, o Zot njeridashës, me ndërmjetimet e shenjtorëve të tu."},{"t":"p","x":"Pa u ndarë nga gjiri prindëror, o Fjalë e Vetëmlindur e Perëndis’, erdhe mbi dhé nga njeridashja, duke u bërë njeri pa ndryshuar, dhe durove Kryq e vdekje trupërisht, ti i papësuari sipas Hyjnisë dhe, si u ngjalle së vdekurish, i fale gjinisë së njerëzve pavdekshmërinë, si i vetmi i Tër’fuqishëm."},{"t":"p","x":"Denjove vdekjen trupërisht dhe na fale pavdekshmërinë, o Shpëtimtar; dhe banove në varr, që të na çlirosh prej Hadhit dhe të na ngjallësh bashk’ me veten tënde, duke pësuar si njeri, po duke u ngjallur si Perëndi. Prandaj po të thërresim: Lavdi më ty, o Zot jetëdhënës, i vetmi Njeridashës."},{"t":"p","x":"Gurët u çanë, o Shpëtimtar, kur u ngrit Kryqit yt në Kalvar; portarët e Hadhit u drodhën kur u vure në varr si njeri; se, duke shkatërruar fuqinë e vdekjes, u fale gjith’ të vdekurve paprishjen me Ngjalljen tënde, o Shpëtimtar. O Zot jetëdhënës, lavdi më ty."},{"t":"p","x":"Gratë dëshiruan të shihnin Ngjalljen tënde, o Krisht Perëndi; erdhi e para Maria Magdalena, gjeti gurin e varrit të rrokullisur dhe engjëllin që rrinte mbi të dhe thoshte: Si kërkoni të gjallin ndër të vdekurit? U ngjall si Perëndi që t’i shpëtojë të gjithë."},{"t":"p","x":"Ku është Jisui, të cilin donit ta ruanit? Thoni, o judenj: Ku është ai që e vut’ në varr dhe ia vulosët gurin? Jepeni të vdekurin, ju që e mohuat Jetën. Jepeni të varrosurin a besojini të ngjallurit. Dhe, në heshtni ju, gurët do të thërresin Ngjalljen e Zotit, dhe për më tepër ai që u rrokullis prej varrit. I madh është përdëllimi yt! I madh është misteri i Ekonomisë sate! Shpëtimtari ynë, lavdi më ty."}]}]},{"n":"Tingulli Tërthor i Të Parit","sections":[{"k":"thirrtoret","part":"mbremesore","title":"Vargëzimet e Thirrtoreve","blocks":[{"t":"p","x":"Me Kryqin tënd të nderuar, o Krisht, turpërove djallin, dhe me Ngjalljen tënde e nxore thumbin e mëkatit dhe na shpëtove nga dyert e vdekjes. Të lavdërojmë, o i Vetëmlindur."},{"t":"p","x":"Ai që i fal Ngjalljen gjinisë së njerëzve, u çua për therje si dele. U tmerruan prej tij krerët e Hadhit dhe u hapën dyert e vuajtjes. Se hyri Krishti, Mbreti i lavdisë, duke u thënë të burgosurve “Dilni”, dhe atyre që ishin në errësirë “Shfaquni”."},{"t":"p","x":"Çudi e madhe! Krijuesi i të padukurave, si pësoi trupërisht nga njeridashja, u ngjall i pavdekuri. Ejani, o breza kombesh, t’i falemi këtij; se, pasi shpëtuam prej kurthit me dhembshurinë e tij, mësuam të himnojmë një Perëndi në tri Hipostaza."},{"t":"p","x":"Adhurimin e mbrëmjes ta ofrojmë ty, Dritës së paperënduar, që shkëlqeve në botë, si në pasqyrë me trup, në mbarim të gjithë jetëve, dhe zbrite në Hadh, dhe shpërndave errësirën e atjeshme, dhe u tregove kombeve dritën e Ngjalljes. O Zot dritëdhënës, lavdi më ty."},{"t":"p","x":"Krishtin, kryetarin e shpëtimit tonë, le ta lavdërojmë; se, kur u ngjall së vdekurish, bota shpëtoi prej mashtrimit, gëzohet kori i engjëjve, ikën mashtrimi i demonëve, Adami i rënë ngrihet, djalli shkatërrohet."},{"t":"p","x":"Rojat udhëzoheshin prej të paudhëve: Fshihni Ngjalljen e Krishtit. Merrni argjende dhe thoni se, kur flinim ne, i vdekuri u vodh prej varrit. Cili pa? Cili dëgjoi që një i vdekur u vodh dhe për më tepër i mirosur dhe lakuriq, pasi la në varr pëlhurat e tij? Mos u mashtroni, o judenj! Mësoni fjalët e profetëve dhe dijeni se ky është me të vërtetë Çliruesi i botës dhe i Tërëfuqishmi."},{"t":"p","x":"O Zot, që plaçkite Hadhin dhe shkele vdekjen; o Shpëtimtari ynë, që ndriçove botën me Kryqin e nderuar, mëshirona."}]},{"k":"dogmatiku","part":"mbremesore","title":"Hyjlindësorja Dogmatike","blocks":[{"t":"p","x":"Në Detin e Kuq u përshkrua dikur ikona e Nuses së pamartuar. Atje Moisiu, që ndau ujin; këtu Gabrieli, shërbëtor’ i çudisë. Atëherë Izraeli kaloi në këmbë përmes thellësisë së detit, pa u lagur; ndërsa tani Virgjëresha lindi Krishtin pa farë. Deti, pas kalimit të Izraelit, mbeti i pashkelur; e Pacenuara, pas lindjes së Emanuelit, mbeti e paprekur. O Perëndi, që je dhe ishe më parë, dhe u shfaqe si njeri, mëshirona."}]},{"k":"pasvargjet","part":"mbremesore","title":"Pasvargjet","blocks":[{"t":"p","x":"Ty, Krishtin Shpëtimtar, që u mishërove dhe nuk u ndave prej qiejve, me zëra dhe këngë po të madhërojmë, se durove Kryq e vdekje për gjininë tonë si Zot njeridashës dhe, pasi theve dyert e Hadhit, u ngjalle pas tri ditësh, duke shpëtuar shpirtrat tanë."},{"t":"p","x":"Kur u shpua brinja jote, o Jetëdhënës, burove për të gjithë rrëke ndjese, jete dhe shpëtimi; dhe denjove vdekjen me trup, duke na dhuruar pavdekshmërinë; dhe, si banove në varr, na çlirove, duke na ngjallur bashk’ me veten tënde lavdërisht si Perëndi. Prandaj po të thërresim: O Zot njeridashës, lavdi më ty."},{"t":"p","x":"Kryqëzimi yt dhe zbritja jote në Hadh, o njeridashës, janë të habitshme; se, si e plaçkite atë pasi ngjalle bashk’ me veten tënde robërit dikur, lavdërisht, si Perëndi, hape Parajsën, dhe i denjësove të gëzojnë. Prandaj, neve që lavdërojmë Ngjalljen tënde të triditshme, dhurona ndjesë mëkatesh, duke na denjësuar të bëhemi banorë të Parajsës, si i vetmi i Mëshirshëm."},{"t":"p","x":"Ti që pranove për ne pësimin në trup, dhe u ngjalle pas tri ditësh prej së vdekurish, shëroji pasionet e trupit ton’, dhe ngrina nga fajet tona të rënda, dhe shpëtona, o Njeridashës."},{"t":"sub","x":"Lavdi dhe tani"},{"t":"sub","x":"Hyjlindësorja"},{"t":"p","x":"Tempull dhe derë je, pallat dhe fron i Mbretit, o Virgjëreshë e Gjith’nderuar, me anën e së cilës Çliruesi im, Zoti Krisht, ndriti mbi ata që flinin në errësirë, duke qenë diell drejtësie dhe duke dashur të ndriçojë ata që gatoi me dorën e vet sipas ikonës së tij. Prandaj, o e Gjith’himnuar, duke pasur përpara tij guxim nënor, ndërmjeto pa pushim që të shpëtohen shpirtrat tanë."}]},{"k":"perleshorja","part":"mengjesore","title":"Përlëshorja Ngjallësore","blocks":[{"t":"p","x":"Fjalën e panisshme bashkë me Atin e me Shpirtin e Shenjtë, që lindi prej Virgjëreshës për shpëtimin tonë, le ta përhimnojmë, o besnikë, e le t’i falemi; se denjoi të ngjitet trupërisht mbi kryq dhe të durojë vdekje dhe të ngjallë të vdekurit me Ngjalljen e tij të lavdëruar."}]},{"k":"hyjlindesorja","part":"mengjesore","title":"Hyjlindësorja Ngjallësore","blocks":[{"t":"p","x":"Gëzohu, derë e Zotit e pakaluar; gëzohu, mur dhe mbrojtje e atyre që rendin te ti; gëzohu, o liman i padimëruar dhe i pamartuar. Ti që linde trupërisht Bërësin tënd dhe Perëndin’, mos resht së ndërmjetuari për ata që të himnojnë dhe adhurojnë Birin tënd."}]},{"k":"ndenjesoret1","part":"mengjesore","title":"Pas Stihologjisë së parë, Ndenjësoret","blocks":[{"t":"sub","x":"Ton sinanarhon Logon"},{"t":"p","x":"Përlëvdojeni Kryqin e Shpëtimtarit Krisht, dhe me këngë Varrimin e tij nderojeni, edhe Ngjalljen pas tri ditësh lavdërojeni, se të burgosurit në Hadh dhe të vdekurit në varr i ngriti Zot’ i fuqishëm, dhe e theu fuqin’ e djallit, dhe i ndriti t’errësuarit."},{"t":"sub","x":"Lavdi"},{"t":"p","x":"O Zot, u shpalle i vdekur, ti që vrave vdekjen; në varr u vendose, ti që zbraze varret; ushtarët përsipër ruanin varrin, dhe ti përposhtë ngjalle të vdekurit ndër shekuj. O Zot i Tër’fuqishëm dhe i pakuptueshëm, lavdi më ty."},{"t":"sub","x":"Tani"},{"t":"sub","x":"Ton sinanarhon Logon"},{"t":"p","x":"Lum e lum ti, o mal, ku bariti Zot’ i madh; lum e lum ti, o ferrë, që nuk u dogje dot; lum e lum, o urë, që na shpie në shpëtim, në Parajs’ e në dëfrim dhe në jetën pa mbarim, o Nën’ e shenjtë, gëzohu, që virgjërisht na ke lindur Shpëtimtarin tonë Jisu Krisht."}]},{"k":"ndenjesoret2","part":"mengjesore","title":"Pas Stihologjisë së dytë, Ndenjësoret","blocks":[{"t":"p","x":"O Zot, pas Ngjalljes sate të triditshme dhe faljes së apostujve, Pjetri të thërriste: Gratë patën guxim, por unë u frikësova. Kusari teologoi, por un’ të mohova. Vallë, a do të më quash më dishepull? Apo do të më bësh përsëri peshkatar deti? Po pritmë të penduar, o Perëndi, dhe shpëtomë."},{"t":"sub","x":"Lavdi"},{"t":"p","x":"O Zot, në mes të të dënuarve të mbërthyen të paudhët, dhe brinjën tënde e shpuan me shtizë, o Përdëllyes; dhe varrim denjove, ti që theve dyert e Hadhit dhe u ngjalle pas tri ditësh; gratë rendën të të shihnin dhe u lajmëruan Ngjalljen apostujve. O Shpëtimtar i përmbilartësuar, që të himnojnë engjëjt, o Zot i bekuar, lavdi më ty."},{"t":"sub","x":"Tani"},{"t":"sub","x":"Ton sinanarhon Logon"},{"t":"p","x":"Virgjëreshë dhe Nënë Mari Hyjlindëse, që hidhërimin e Evës e ktheve në gëzim, të himnojmë ne besnikët dhe të falemi, se na çlirove plotësisht nga mallkimi prindëror, o Zonj’ e Përmbibekuar, pra lutu për ne paprerë dhe shpëtona prej rreziqeve."}]},{"k":"degjimi","part":"mengjesore","title":"Dëgjimi","blocks":[{"t":"p","x":"Me mendje të habitur nga pamja engjëllore, dhe me shpirt të ndriçuar nga Ngjallja e hyjshme, miroprurëset u ungjillëzonin apostujve: Shpalluni kombeve Ngjalljen e Zotit, i cili do të bashkëveprojë me ju përmes mrekullive dhe do të na falë përdëllimin e madh."}]},{"k":"shkallesat","part":"mengjesore","title":"Shkallesat","blocks":[{"t":"sub","x":"Antifoni i parë"},{"t":"p","x":"Në hidhërimin tim të këndoj si Davidi, o Shpëtimtari im. Shpëtoma shpirtin prej gjuhës dinake."},{"t":"p","x":"Jeta ësht’ e lumur për eremitët, se fluturojnë me dashuri hyjnore."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Prej Shpirtit të Shenjtë sundohen të gjitha të dukurat e të padukurat; se, duke qenë i vet’pushtetshëm, është me të vërtetë një prej Trinisë."},{"t":"sub","x":"Antifoni i dytë"},{"t":"p","x":"Le të ngjitemi në male, o shpirt; le të shkojmë atje nga vjen ndihma."},{"t":"p","x":"Dora jote e djathtë, o Krisht, le të qëndrojë mbi mua, duke më ruajtur nga çdo mjerim."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Shpirtit të Shenjtë, duke teologuar, le t’i themi: Ti je Perëndi, jetë, dashuri, dritë, mendje; ti je mirësi, ti mbretëron përjetë."},{"t":"sub","x":"Antifoni i tretë"},{"t":"p","x":"I mbushur me gëzim të madh po lutem për ata që më kanë thënë: Le të shkojmë në oborret e Zotit."},{"t":"p","x":"Në shtëpinë e Davidit kryhen gjëra të frikshme, se atje ësht’ zjarri që djeg çdo mendje të turpshme."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Shpirtit të Shenjtë i përket vlera jetëkrijuese, se prej tij merr shpirt çdo qenie e gjallë; siç i përket Atit bashkë me Fjalën."}]},{"k":"paravargu","part":"mengjesore","title":"Paravargu","blocks":[{"t":"p","x":"Ngrihu, o Zot, Perëndia im, se ti mbretëron përjetë."},{"t":"sub","x":"Vargu: Do të të lavdëroj, o Zot, me gjith’ zemrën time."}]},{"k":"shkurtorja","part":"mengjesore","title":"Shkurtorja","blocks":[{"t":"p","x":"Në Hadh denjove të zbrisje, o Shpëtimtari im, dhe, pasi i theve dyert si i Tërëfuqishëm, i ngjalle të vdekurit bashkë me veten tënde si Krijues; e hoqe thumbin e vdekjes dhe e shpëtove Adamin prej mallkimit, o Njeridashës. Prandaj të gjithë të thërresim: O Zot, shpëtona."}]},{"k":"shtepia","part":"mengjesore","title":"Shtëpia","blocks":[{"t":"p","x":"Kur dëgjuan fjalët e engjëllit, gratë u gëzuan dhe pushuan vajtimin, dhe të trembura po shikonin Ngjalljen; dhe ja Krishti iu afrua atyre duke u thënë: Gëzohuni! Kini kurajë! Unë e munda botën dhe i shpëtova të robëruarit. Shpejtoni, pra, te dishepujt që t’i lajmëroni se i pres në qytetin e Galilesë për të predikuar. Prandaj të gjithë të thërresim: O Zot, shpëtona."}]},{"k":"lavderimet","part":"mengjesore","title":"Vargëzimet e Lavdërimeve","blocks":[{"t":"p","x":"O Zot, kur ishte varri i vulosur prej të paligjve, dole prej tij, sikundër linde prej Hyjlindëses; nuk e kuptuan, si u mishërove, engjëjt e tu pa trup; nuk të ndjenë kur u ngjalle, ushtarët që të ruanin; se që të dyja këto janë të vulosura për ata që kërkojnë, dhe u janë shfaqur çuditë atyre që i falen misterit me besë. Neve që e përhimnojmë, jepna si shpërblim ngazëllimin dhe përdëllimin e madh."},{"t":"p","x":"O Zot, duke dërrmuar kyçet e përjetshme dhe duke thyer zinxhirët, u ngjalle prej varrit, pasi le pëlhurat si dëshmi të vërtetë të varrimit tënd të triditshëm dhe shkove përpara në Galile, ti që të ruanin në shpellë. Mëshira jote është e madhe. O Shpëtimtar i pakuptueshëm, mëshirona."},{"t":"p","x":"O Zot, gratë rendën në varr të të shikonin ty, Krishtin, që pësove për ne; dhe kur erdhën pranë, gjetën një engjëll që rrinte mbi gur, i cili u rrokullis nga frika; dhe ai thirri duke thënë: U ngjall Zoti. Thojuni dishepujve se u ngjall së vdekurish, ai që shpëton shpirtrat tanë."},{"t":"p","x":"O Zot, sikundër dole nga varri i vulosur, ashtu hyre dhe nga dyert e mbyllura ndër dishepujt e tu, dhe u tregove pësimet e trupit që denjove, o Shpëtimtar, nga zemërgjerësia. Si pasardhës i Davidit, durove plagë dhe, si Bir i Perëndisë, çlirove botën. Mëshira jote ësht’ e madhe. O Shpëtimtar i pakuptueshëm, mëshirona."},{"t":"p","x":"O Zot, o Mbret i jetëve dhe Krijues i gjithësisë, që denjove trupërisht kryqëzim dhe varrim për ne, që të na çlirosh të gjithë pra prej Hadhit, ti je Perëndia ynë, përveç teje nuk njohim tjetër."},{"t":"p","x":"O Zot, kush do t’i tregojë çuditë e tua të përmbishkëlqyera? A kush do t’i shpallë misteret e tua të frikshme? Se u bëre njeri për ne, sikundër deshe vetë, dhe shfaqe pushtetin e fuqisë sate; se me Kryqin tënd i çele kusarit Parajsën, dhe me Varrimin tënd dërrmove kyçet e Hadhit, dhe me Ngjalljen tënde pasurove gjithësinë. O Zemërdhembshur, lavdi më ty."},{"t":"p","x":"Gratë miroprurëse shkuan në varrin tënd herët në mëngjes, dhe kërkonin të mirosnin ty, Fjalën dhe Perëndinë e pavdekshëm; dhe, si dëgjuan fjalët e engjëllit, u kthyen me gëzim që t’u lajmëronin apostujve hapur që u ngjalle ti, o jeta e të gjithëve, dhe i fale botës ndjesën dhe përdëllimin e madh."},{"t":"p","x":"Rojat e varrit hyjpritës u thoshin judenjve: Oh, këshilla juaj e kotë! U munduat më kot, duke u përpjekur të ruanit të Papërshkruarin! E shfaqët më madhërisht duke dashur të fshihnit Ngjalljen e të Kryqëzuarit. Oh, Këshilli juaj i kotë! Përse prapë këshilloheni të fshihni atë që nuk fshihet? Por më mirë dëgjoni prej nesh dhe kini mirësinë të besoni të vërtetën e ngjarjeve. Një engjëll që vetëtinte, zbriti prej qiellit dhe rrokullisi gurin, nga frika e të cilit ne u bëmë si të vdekur; dhe u thirri grave miroprurëse, mendjeforta dhe u tha: Nuk e shihni vdekjen e rojave, dhe zgjidhjen e vulave, dhe zbrazjen e Hadhit? Si e kërkoni si të vdekur atë që shkatërroi triumfin e Hadhit dhe hoqi thumbin e vdekjes? Por shkoni shpejt dhe t’u ungjillëzoni Ngjalljen apostujve, duke thirrur pa frikë: Me të vërtetë u ngjall Zoti, që ka përdëllimin e madh."}]}]},{"n":"Tingulli Tërthor i Të Dytit","sections":[{"k":"thirrtoret","part":"mbremesore","title":"Vargëzimet e Thirrtoreve","blocks":[{"t":"p","x":"Duke pasur fitoren kundër Hadhit, o Krisht, u ngjite në Kryq, që të ngjallësh bashkë me veten tënde ata që rrinin në errësirën e vdekjes. O Shpëtimtar i Tër’fuqishëm, si i lirë ndër të vdekurit, që buron jetë prej dritës sate, mëshirona."},{"t":"p","x":"Sot Krishti, pasi shkeli vdekjen sikundër tha, u ngjall dhe i dhuroi botës ngazëllimin, që të themi të gjithë himnin, duke thirrur kështu: O Burim’ i jetës, o dritë e paafruar, Shpëtimtar i Tër’fuqishëm, mëshirona."},{"t":"p","x":"Nga ti, o Zot, që je në tërë krijesën, ku do të shkojmë ne mëkatarët? Në qiell? Ti rri atje vetë; në Hadh? Atje shkele vdekjen; në thellësi të detit? Atje është dora jote, o Zot. Te ti pra vijmë e të biem në gjunjë, dhe të lutemi: Ti që u ngjalle së vdekurish, mëshirona."},{"t":"p","x":"Me Kryqin tënd, o Krisht, mburremi, dhe Ngjalljen tënde himnojmë dhe lavdërojmë. Se ti je Perëndia ynë, përveç teje nuk njohim tjetër."},{"t":"p","x":"Duke bekuar kurdoherë Zotin, himnojmë Ngjalljen e tij, se duroi Kryq dhe shkatërroi vdekjen me vdekje."},{"t":"p","x":"Lavdi fuqisë sate, o Zot, se shkatërrove atë që kishte pushtetin e vdekjes. Na përtërite me anën e Kryqit tënd, dhe na dhurove jetën dhe paprishjen."},{"t":"p","x":"Varrimi yt, o Zot, dërrmoi dhe theu zinxhirët e Hadhit. Ngjallja jote prej së vdekurish, ndriçoi botën. O Zot, lavdi më ty."}]},{"k":"dogmatiku","part":"mbremesore","title":"Hyjlindësorja Dogmatike","blocks":[{"t":"p","x":"Cili nuk do të të lumërojë, o Virgjëreshë e Tërëshenjtë? Cili nuk do të përhimnojë lindjen tënde të kulluar? Se Biri yt i Vetëmlindur, që shkëlqeu prej Atit pa kohë, lindi prej teje së Qashtrës dhe u mishërua pa shpjegim, duke qenë nga natyra Perëndi, dhe duke u bërë për ne njeri nga natyra, jo i ndarë në dy persona, por i njohur në dy natyra të papërziera. Atij lutju, o Zonjë e Tër’lumur, të mëshirohen shpirtrat tanë."}]},{"k":"pasvargjet","part":"mbremesore","title":"Pasvargjet","blocks":[{"t":"p","x":"Ngjalljen tënde, o Krisht Shpëtimtar, engjëjt e himnojnë në qiej. Denjësona dhe ne përmbi dhé, që të të lavdërojmë me zemër të pastër."},{"t":"p","x":"Duke thyer dyert prej bronzi dhe duke dërrmuar kyçet e Hadhit, si Perëndi i Tër’fuqishëm, ngjalle gjininë e rënë të njerëzve. Prandaj dhe ne njëzëri thërresim: O Zot, që u ngjalle së vdekurish, lavdi më ty."},{"t":"p","x":"Krishti, duke dashur të na ngrejë nga rënia e vjetër, mbërthehet në Kryq dhe vihet në varr; atë pra gratë miroprurëse e kërkonin me lot dhe, duke vajtuar, thoshin: Mjerë ne, o Shpëtimtar i të gjithëve! Si denjove të banosh në varr? Dhe, pasi deshe të banosh në të, si të vodhën? Ku gjetkë të vendosën? Dhe cili vend fshehu Trupin tënd Jetëprurës? Por, o Kryezot, siç u zotove, shfaqu te ne dhe pushona vajtimin e lotëve. Dhe tek vajtonin, një engjëll u thirri: Pushoni vajtimin, t’u thoni apostujve që u ngjall Zoti dhe i dhuroi botës ndjesën dhe përdëllimin e madh."},{"t":"p","x":"Pasi u kryqëzove siç deshe, o Krisht, dhe, pasi plaçkite vdekjen me varrimin tënd, u ngjalle pas tri ditësh me lavdi si Perëndi, dhe i dhurove botës jetën e pasosur dhe përdëllimin e madh."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"sub","x":"Hyjlindësorja"},{"t":"p","x":"Zoti Krisht, Krijuesi dhe Çliruesi im, o e Gjithëqashtër, si lindi prej teje i veshur si un’, çliroi Adamin prej mallkimit të mëparshëm. Prandaj, o e Gjith’qashtër, si Nënë Perëndie dhe Virgjëreshë me të vërtetë, të thërresim pa pushim përshëndetjen e engjëllit: Gëzohu, o Zonjë, mbrojtje dhe strehë, dhe shpëtim i shpirtrave tanë."}]},{"k":"perleshorja","part":"mengjesore","title":"Përlëshorja Ngjallësore","blocks":[{"t":"p","x":"Fuqitë Engjëllore erdhën mbi varrin tënd, dhe ata që ruanin u bënë si të vdekur; dhe qëndronte Maria në varr, duke kërkuar trupin tënd të pacenuar. E plaçkite Hadhin, pa u ngarë prej tij; takove Virgjëreshën, duke dhuruar jetë. O Zot, që u ngjalle së vdekurish, lavdi më ty."}]},{"k":"hyjlindesorja","part":"mengjesore","title":"Hyjlindësorja Ngjallësore","blocks":[{"t":"p","x":"Ti që quajte Nënën tënde të bekuar, erdhe te Pësimi me vullnetin tënd, dhe shkëlqeve në Kryq, duke dashur të kërkosh Adamin, duke u thënë engjëjve: Përgëzomëni, se u gjet dhrahmia e humbur. Ti, që i rregullove të gjitha urtësisht, lavdi më ty."}]},{"k":"ndenjesoret1","part":"mengjesore","title":"Pas Stihologjisë së parë, Ndenjësoret","blocks":[{"t":"p","x":"Kur ishte varri i hapur dhe Hadhi vajtonte, Maria u thërriste apostujve që ishin fshehur: Dilni, o punëtorë të vreshtit, lëçitni lajmin e Ngjalljes. U ngjall Zoti, duke i dhuruar botës përdëllimin e madh."},{"t":"sub","x":"Lavdi"},{"t":"p","x":"O Zot, Maria Magdalena qëndronte pranë varrit dhe qante duke thirrur dhe, duke të pandehur si kopshtar, thoshte: Ku e vure Jetën e amshuar? Ku e fshehe atë që rri mbi fron kerubik? Se ata që e ruanin, u bënë si të vdekur nga frika. Ose më jepni Zotin tim, ose thërrisni bashkë me mua: Ti që ishe ndër të vdekurit dhe i ngjalle të vdekurit, lavdi më ty."},{"t":"sub","x":"Tani"},{"t":"p","x":"Gedeoni parathotë ngjizjen dhe Davidi shpjegon lindjen tënde, o Hyjlindëse. Se Fjala zbriti në gjirin tënd si shiu mbi lëmsh, dhe ti, o tokë e shenjtë, lulëzove pa mbjellje shpëtimin e botës, Krishtin, Perëndinë tonë, o Hirplote."}]},{"k":"ndenjesoret2","part":"mengjesore","title":"Pas Stihologjisë së dytë, Ndenjësoret","blocks":[{"t":"p","x":"Jeta dergjej në varr dhe një vulë ishte mbi gur. Ushtarët e ruanin Krishtin si një Mbret që flinte dhe, si goditi pa u dukur armiqt’ e tij, u ngjall Zoti."},{"t":"sub","x":"Lavdi"},{"t":"p","x":"Jonai parathotë varrin tënd dhe Simeoni shpjegon Ngjalljen e hyjshme, o Zot i pavdekshëm. Dhe zbrite si i vdekur në varr, ti që theve dyert e Hadhit; dhe u ngjalle pa prishje, si Kryezot, për shpëtimin e botës, o Krisht, Perëndia yn’, që ndriçove ata që ishin në errësirë."},{"t":"sub","x":"Tani"},{"t":"p","x":"O Hyjlindëse Virgjëreshë, lutju Birit tënd, që u mbërthye në Kryq vullnetarisht dhe që u ngjall së vdekurish, Krishtit, Perëndisë tonë, që t’i shpëtojë shpirtrat tanë."}]},{"k":"degjimi","part":"mengjesore","title":"Dëgjimi","blocks":[{"t":"p","x":"Pasi shembe dyert e Hadhit, o Krisht, me vdekjen tënde vullnetare dhe jetëbërëse, si Perëndi, e hape për ne Parajsën e vjetër dhe, pasi u ngjalle prej së vdekurish, e shpëtove jetën tonë nga prishja."}]},{"k":"shkallesat","part":"mengjesore","title":"Shkallesat","blocks":[{"t":"sub","x":"Antifoni i parë"},{"t":"p","x":"Në qiell i ngre syt’ e mi, drejt teje, o Fjalë. Ki mëshirë për mua, që të jetoj për ty."},{"t":"p","x":"Mëshirona ne të poshtëruarit, duke na trajtuar si enë të dobishme, o Fjalë."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Shpirti i Shenjtë është shkaku i gjith’ shpëtimit. Po t’i fryjë ky ndonjërit pas vlerës, menjëherë e ngre përsipër gjërave të tokës, i jep krahë, e bën të rritet dhe e ngre lart atë."},{"t":"sub","x":"Antifoni i dytë"},{"t":"p","x":"Po të mos ishte Zoti me ne, asnjë s’do të mund t’i bënte ballë armikut në luftë, se fituesit lartësohen prej tij."},{"t":"p","x":"Shpirti im mos u zëntë në dhëmbët e tyre si harabel, o Fjalë. I mjeri unë! Si kam për të shpëtuar prej armiqve, duke qenë mik i mëkatit?"},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Shpirti i Shenjtë është hyjnizim për të gjithë, mirëdashje, urtësi, paqe dhe bekim, se ai vepron njëlloj si Ati dhe Fjala."},{"t":"sub","x":"Antifoni i tretë"},{"t":"p","x":"Ata që kanë besim te Zoti, janë të frikshëm për armiqtë dhe të admirueshëm për të gjithë, se shikojnë lart."},{"t":"p","x":"Të drejtët, duke të pasur ndihmës, nuk i zgjatin duart e tyre në paudhësi, o Shpëtimtar."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Shpirti i Shenjtë ka pushtet mbi të gjitha; atë pra e adhurojnë ushtritë përsipër me çdo frymë përposhtë."}]},{"k":"paravargu","part":"mengjesore","title":"Paravargu","blocks":[{"t":"p","x":"O Zot, ngri dinastinë tënde, dhe eja të na shpëtosh."},{"t":"sub","x":"Vargu: Vështro, ti që ruan Izraelin."}]},{"k":"shkurtorja","part":"mengjesore","title":"Shkurtorja","blocks":[{"t":"p","x":"Pasi i ngjalli tërë të vdekurit nga gropat e errëta me pëllëmbën e tij jetëkrijuese, Krishti, Perëndia jetëdhënës, i fali Ngjalljen si trofe trupit të vdekshëm; se ai është Shpëtimtari i të gjithëve, Ngjallja dhe Jeta, dhe Perëndia i gjithësisë."}]},{"k":"shtepia","part":"mengjesore","title":"Shtëpia","blocks":[{"t":"p","x":"Kryqit dhe Varrimit tënd u thurim himne dhe u falemi ne besnikët, o Jetëdhënës; se, si Perëndi i tërëfuqishëm, e lidhe Hadhin, o i Pavdekshëm, dhe i ngjalle të vdekurit bashkë me veten tënde, dhe i shkatërrove dyert e Hadhit dhe, si Perëndi, e rrëzove pushtetin e vdekjes. Prandaj dhe ne, të krijuarit prej balte, të lavdërojmë plot dashuri ty që u ngjalle dhe e rrëzove pushtetin e armikut gjithëshkatërrues, dhe i ngjalle tërë ata që besuan te ti, dhe e çlirove botën nga shigjetat e gjarprit dhe, si i vetmi i Fuqishëm, na çlirove prej kurthit të armikut. Prandaj himnojmë me shpresëtari Ngjalljen tënde, me anë të së cilës na shpëtove, si Perëndi i gjithësisë."}]},{"k":"lavderimet","part":"mengjesore","title":"Vargëzimet e Lavdërimeve","blocks":[{"t":"p","x":"Kryqi yt, o Zot, është jetë dhe ngjallje për popullin tënd; dhe, duke pasur besim në të, të himnojmë ty, Perëndinë tonë, që u ngjalle. Mëshirona."},{"t":"p","x":"Varrimi yt, o Zot, i çeli Parajsën gjinisë së njerëzve; dhe, si u çliruam prej prishjes, të himnojmë ty, Perëndinë tonë, që u ngjalle. Mëshirona."},{"t":"p","x":"Bashk’ me Atin dhe me Shpirtin le të përhimnojmë Krishtin, që u ngjall së vdekurish, dhe le t’i thërresim: Ti je jeta dhe ngjallja për ne. Mëshirona."},{"t":"p","x":"U ngjalle pas tri ditësh prej varrit, o Krisht, sikundër është shkruar, duke bashkëngjallur dhe Stërgjyshin tonë. Prandaj të lavdëron gjinia e njerëzve dhe e përhimnon Ngjalljen tënde."},{"t":"p","x":"O Zot, misteri i Ngjalljes sate është i madh dhe i çuditshëm; se dole prej varrit si dhëndri prej nusërores, duke shkelur vdekjen me vdekje, që të çlirosh Adamin. Prandaj engjëjt vallëzojnë në qiej, dhe njerëzit mbi dhé e lavdërojnë zemërdhembshurinë që tregove për ne, o Njeridashës."},{"t":"p","x":"O judenj të paligjshëm, ku janë vulat dhe argjendet që u dhatë ushtarëve? Nuk u vodh thesari, por u ngjall si i fortë, dhe ju u turpëruat, duke mohuar Krishtin, Zotin e lavdisë, që pësoi dhe u varros, dhe u ngjall së vdekurish. Atij le t’i falemi."},{"t":"p","x":"Kur e vulosët varrin, dhe vendosët roja dhe vutë shenja, si jua vodhën, o judenj? Ndërkohë që dyert ishin të mbyllura, Mbreti doli. Ose silleni si të vdekur, ose adhurojeni si Perëndi, duke kënduar me ne: Lavdi, o Zot, Kryqit tënd dhe Ngjalljes sate."},{"t":"p","x":"Gratë miroprurëse shkuan te varri yt jetëdhënës duke vajtuar, o Zot; dhe, duke mbajtur miro, kërkonin të mirosnin Trupin tënd të pacenuar, por gjetën një engjëll dritëprurës që rrinte mbi gur, i cili u foli duke u thënë: Si lotoni për atë që i buroi botës jetën nga brinja? Si e kërkoni si të vdekur në varr të Pavdekurin? Por rendni me miro dhe t’u lajmëroni dishepujve të tij gëzimin e përbotshëm të Ngjalljes së tij të lavdëruar, me të cilën ndriçona dhe ne, o Shpëtimtar, dhe dhurona ndjesën dhe përdëllimin e madh."}]}]},{"n":"Tingulli i Rëndë","sections":[{"k":"thirrtoret","part":"mbremesore","title":"Vargëzimet e Thirrtoreve","blocks":[{"t":"p","x":"Ejani të ngazëllohemi në Zotin, i cili dërrmoi pushtetin e vdekjes dhe ndriçoi gjininë e njerëzve, duke thirrur bashkë me engjëjt: O Krijues dhe Shpëtimtari ynë, lavdi më ty."},{"t":"p","x":"Kryq durove, o Shpëtimtar, dhe varrim për ne; dhe me vdekje vrave vdekjen si Perëndi. Prandaj i falemi Ngjalljes sate të triditshme. O Zot, lavdi më ty."},{"t":"p","x":"Apostujt, kur panë Ngritjen e Krijuesit, u çuditën, dhe lëçitën lavdërimin engjëllor. Kjo është lavdia e Kishës. Kjo është pasuria e Mbretërisë. O Zot, që pësove për ne, lavdi më ty."},{"t":"p","x":"Megjithëse u kape, o Krisht, prej burrash të paligjshëm, por ti je Perëndia im, dhe nuk e kam për turp; u fshikullove në kurriz, nuk e mohoj; u mbërtheve në Kryq, dhe nuk e fsheh; me Ngjalljen tënde mburrem, se vdekja jote është jeta ime. O Zot i tër’fuqishëm dhe njeridashës, lavdi më ty."},{"t":"p","x":"Duke përmbushur profecinë e Davidit, Krishti u zbuloi nxënësve në Sion madhështin’ e tij, duke e shfaqur veten e tij përherë të himnuar dhe të lavdëruar bashkë me Atin dhe me Shpirtin e Shenjtë, më parë si Fjalë pa trup, më pas të mishëruar për ne; dhe të vdekur si njeri, e të ngjallur sipas fuqisë së tij, si Njeridashës."},{"t":"p","x":"Zbrite në Hadh, o Krisht, siç deshe vetë, plaçkite vdekjen si Perëndi dhe Kryezot; dhe u ngjalle pas tri ditësh, duke bashkëngjallur Adamin nga zinxhirët e Hadhit dhe nga prishja, që të thërret e të thotë: Lavdi Ngjalljes sate, i vetmi Njeridashës."},{"t":"p","x":"U vure në varr si i fjetur, o Zot, dhe u ngjalle pas tri ditësh, si i fortë nga fuqia, duke bashkëngjallur Adamin nga prishja e vdekjes, si i Tër’fuqishëm."}]},{"k":"dogmatiku","part":"mbremesore","title":"Hyjlindësorja Dogmatike","blocks":[{"t":"p","x":"Ti u njohe si Nënë përmbi natyrë, o Hyjlindëse, dhe Virgjëreshë mbete përmbi çdo arsye dhe mendim; dhe mrekullinë e lindjes sate asnjë gjuhë nuk mund ta shpjegojë; se, duke qenë e çuditshme ngjizja, o e Kulluar, edhe mënyra e lindjes ësht’ e pakuptueshme; se, kur do Perëndia, mposhtet ligji i natyrës. Prandaj, duke të njohur të gjithë si Nënë Perëndie, të lutemi nxehtësisht: Ndërmjeto të shpëtohen shpirtrat tanë."}]},{"k":"pasvargjet","part":"mbremesore","title":"Pasvargjet","blocks":[{"t":"p","x":"U ngjalle prej varrit, Shpëtimtar i botës, dhe bashkëngjalle njerëzit me trupin tënd. O Zot, lavdi më ty."},{"t":"p","x":"Ejani t’i falemi atij që u ngjall prej së vdekurish dhe i ndriçoi të gjitha; dhe na çliroi nga tirania e Hadhit me anën e Ngjalljes së tij të triditshme, dhe na fali jetën dhe përdëllimin e madh."},{"t":"p","x":"Zbrite më poshtë Hadhit, o Krisht, dhe plaçkite vdekjen; dhe, si u ngjalle pas tri ditësh, ti na ngjalle dhe ne që lavdërojmë Ngjalljen tënde të gjith’fuqishme, o Zot njeridashës."},{"t":"p","x":"I frikshëm u duke, o Zot, kur u shtrive në varr si i fjetur; dhe pasi u ngjalle pas tri ditësh si i fuqishëm, ti e ngjalle Adamin që thërret: Lavdi Ngjalljes sate, i vetmi Njeridashës."},{"t":"sub","x":"Lavdi dhe tani"},{"t":"sub","x":"Hyjlindësorja"},{"t":"p","x":"Nën strehën tënde, o Zonjë, shkojmë ne të gjithë të dheshmit duke të thirrur ty: O Hyjlindëse, shpresa jon’, shpëtona nga fajet e shumta dhe shpëtoji shpirtrat tanë."}]},{"k":"perleshorja","part":"mengjesore","title":"Përlëshorja Ngjallësore","blocks":[{"t":"p","x":"Dërrmove vdekjen me Kryqin tënd; i çele kusarit Parajsën; e ndryshove vajtimin e miroprur’seve, dhe apostujve të tu u urdhërove të lëçitnin; se u ngjalle, o Krisht Perëndi, dhe i fale botës përdëllimin e madh."}]},{"k":"hyjlindesorja","part":"mengjesore","title":"Hyjlindësorja Ngjallësore","blocks":[{"t":"p","x":"Si thesar i ngjalljes sonë, o e Gjith’himnuar, nxirri prej errësirës dhe gropës së fajeve ata që kanë besim te ti. Se ti i shpëtove fajtorët e mëkatit, duke lindur shpëtimin ti që ishe: Virgjëreshë para lindjes, Virgjëreshë në lindje dhe mbete dhe pas lindjes Virgjëreshë."}]},{"k":"ndenjesoret1","part":"mengjesore","title":"Pas Stihologjisë së parë, Ndenjësoret","blocks":[{"t":"p","x":"Jeta dergjej në varr dhe një vulë ishte mbi gur; ushtarët e ruanin Krishtin si një Mbret që flinte, dhe engjëjt e lavdëronin si Perëndi të pavdekshëm, dhe gratë thërrisnin: U ngjall Zoti, që i fal botës përdëllimin e madh."},{"t":"sub","x":"Lavdi"},{"t":"p","x":"O Krisht Perëndi, që plaçkite vdekjen me varrimin tënd të triditshëm dhe ngjalle njeriun e prishur me Ngjalljen tënde jetëprurëse, si Njeridashës, lavdi më ty."},{"t":"sub","x":"Tani"},{"t":"p","x":"Hyjlindëse Virgjëreshë, lutju pa pushim Krishtit, Perëndisë, që u kryqëzua për ne dhe u ngjall, dhe rrëzoi pushtetin e vdekjes, që të shpëtojë shpirtrat tanë."}]},{"k":"ndenjesoret2","part":"mengjesore","title":"Pas Stihologjisë së dytë, Ndenjësoret","blocks":[{"t":"p","x":"Duke qenë varri i vulosur, o Jetë, dole prej varrit, o Krisht Perëndi, dhe, duke qenë dyert e mbyllura, qëndrove përpara dishepujve, o Ngjallja e të gjithëve, duke përtëritur te ne, me anën e tyre, Shpirt të drejtë, sipas përdëllimit tënd të madh."},{"t":"sub","x":"Lavdi"},{"t":"p","x":"Gratë rendën në varr me lot, duke sjellë miro dhe, kur të ruanin ushtarët ty, Mbretin e të gjithëve, thoshin me vete: Cili do të na e rrokullisë gurin prej varrit? Dhe dëgjuan zë engjëlli që u thoshte: U ngjall Engjëlli i Këshillës së madhe, duke shkelur vdekjen. O Zot i tër’fuqishëm dhe i pakuptueshëm, lavdi më ty."},{"t":"sub","x":"Tani"},{"t":"p","x":"Gëzohu, o Hirplote Hyjlindëse Virgjëreshë, liman dhe mbrojtje e gjinisë së njerëzve; se prej teje u mishërua Çliruesi i botës; se vetëm ti je Nënë dhe Virgjëreshë, përherë e bekuar dhe e lavdëruar; ndërmjeto te Krishti, Perëndia, që t’i dhurojë paqen gjithë botës."}]},{"k":"degjimi","part":"mengjesore","title":"Dëgjimi","blocks":[{"t":"p","x":"Ti që more formën tonë dhe durove Kryq trupërisht, shpëtomë me Ngjalljen tënde, o Krisht Perëndi, si njeridashës."}]},{"k":"shkallesat","part":"mengjesore","title":"Shkallesat","blocks":[{"t":"sub","x":"Antifoni i parë"},{"t":"p","x":"O Shpëtimtar, që ktheve prej mashtrimit robërinë e Sionit, jepmë jetë dhe mua, duke më nxjerrë nga robëria e pasioneve."},{"t":"p","x":"Ai që mbjell hidhërime si dhe kreshmime me lot në jug, do të korrë duaj gëzimi, për ushqim të jetës së amshuar."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Te Shpirti i Shenjtë është burimi i thesareve hyjnore, se prej tij vijnë urtësia, mençuria, frika; atij i ka hije lavdërimi, lavdia, nderi dhe fuqia."},{"t":"sub","x":"Antifoni i dytë"},{"t":"p","x":"Në mos e ndërtoftë Zoti shtëpinë e shpirtit, më kot mundohemi. Se pa atë nuk mund të kryhet as punë, as fjalë."},{"t":"p","x":"Prej frytit të barkut shenjtorët, të nxitur nga Shpirti, mbijnë doktrinat atërore të birësimit."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Me anën e Shpirtit të Shenjtë çdo gjë merr jetë; se ky është Perëndi përpara të gjithëve, zotërues mbi gjithçka, drit’ e paafrueshme, jeta e të gjithëve."},{"t":"sub","x":"Antifoni i tretë"},{"t":"p","x":"Ata që i kanë frikë Zotit, duke gjetur udhët e jetës, do të lumërohen tani e përherë me lavdi të amshuar."},{"t":"p","x":"Duke parë stërnipërit e tu si lisa rreth tryezës sate, gëzohu e dëfre, duke ia shpënë Krishtit, o kryebari."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Shpirti i Shenjtë është det dhuratash, pasuri lavdie, thellësi e madhe gjykimesh, se ai adhurohet si i njëlavdishëm me Atin e me Birin."}]},{"k":"paravargu","part":"mengjesore","title":"Paravargu","blocks":[{"t":"p","x":"Ngrihu, o Zot, Perëndia im, lartësoje dorën, mos i harro të varfrit e tu gjer në fund."},{"t":"sub","x":"Vargu: Do të të lavdëroj, o Zot, me gjith’ zemrën time."}]},{"k":"shkurtorja","part":"mengjesore","title":"Shkurtorja","blocks":[{"t":"p","x":"Pushteti i vdekjes nuk do të mund të zotërojë më mbi njerëzit, se Krishti zbriti në të, duke dërrmuar e shkatërruar fuqinë e saj. Hadhi tashmë u lidh, dhe profetët ngazëllehen njëzëri, duke thënë: Erdhi Shpëtimtari për besimtarët. Dilni, pra, o besimtarë me Ngjalljen."}]},{"k":"shtepia","part":"mengjesore","title":"Shtëpia","blocks":[{"t":"p","x":"Të nëndheshmet e përposhtme, Hadhi dhe vdekja, sot u trembën përpara njërit prej Trinisë. Toka u trondit dhe portarët e Hadhit u drodhën kur të panë, ndërsa e tërë krijesa, bashkë me profetët, i psal e gëzuar këngë triumfale Shpëtimtarit tonë Perëndi, i cili shembi tani fuqinë e vdekjes. Le të brohorasim e le të thërresim: Ky dru e futi Adamin dhe pasardhësit e tij në Parajsë. Dilni, pra, o besimtarë me Ngjalljen."}]},{"k":"lavderimet","part":"mengjesore","title":"Vargëzimet e Lavdërimeve","blocks":[{"t":"p","x":"U ngjall Krishti prej së vdekurish, duke zgjidhur zinxhirët e vdekjes. Ungjillëzo, o tokë, gëzim të madh; këndoni, o qiej, për lavdin’ e Perëndisë."},{"t":"p","x":"Meqenëse pam’ Ngjalljen e Krishtit, le t’i falemi të shenjtit, Zotit Jisu, të vetmit të pamëkatshëm."},{"t":"p","x":"Ngjalljes së Krishtit, nuk pushojmë së faluri; se ai na shpëtoi nga paudhësitë tona, Zoti i shenjtë Jisu, që na tregoi Ngjalljen."},{"t":"p","x":"Si do t’ia shpaguajmë Zotit për gjith’ ato që na dhuroi? Për ne erdhi Perëndia midis njerëzve. Për natyrën ton’ të shthurur Fjala mori trup dhe banoi ndër ne; për mosmir’njohësit, Mirëbërësi; për robërit, Çlirimtari; për ata që rrinin në errësirë, Dielli i drejtësisë; mbi Kryq, i papësuari; në Hadh, Drita; në vdekje, jeta, Ngjallja për të rënët. Atij le t’i thërresim: O Perëndia ynë, lavdi më ty."},{"t":"p","x":"Dërrmove dyert e Hadhit, o Zot, dhe shkatërrove pushtetin e vdekjes me forcën tënde të fuqishme, dhe bashkëngjalle të vdekurit, që flinin në errësirë që prej shekujsh, me Ngjalljen tënde të hyjshme dhe të lavdëruar, si Mbret i gjithësisë dhe Perëndi i tër’fuqishëm."},{"t":"p","x":"Ejani të ngazëllohemi më Zotin dhe të dëfrejmë me Ngjalljen e tij, se i bashkëngjalli të vdekurit nga zinxhirët e pazgjidhshëm të Hadhit, dhe i dhuroi botës, si Perëndi, jetën e amshuar dhe përdëllimin e madh."},{"t":"p","x":"Një engjëll i ndritshëm rrinte mbi gurin e varrit jetëdhënës dhe i ungjillëzonte gratë miroprurëse, duke thënë: U ngjall Zoti, siç ju paratha; lajmërojini dishepujt e tij që i pret në Galile, edhe botës i fal jetën e amshuar dhe përdëllimin e madh."},{"t":"p","x":"Përse e hodhët tej gurin e qoshes, o judenj të paligjshëm? Ky është guri që vuri Perëndia në Sion, që buroi prej shkëmbit ujë në shkretëtirë, dhe bëri të rrjedhë pavdekësi për ne prej brinjës së tij; ky është guri që u shkëput nga një mal Virgjëror, pa dëshirën e një burri: i Biri i njeriut, që vjen mbi ret’ e qiellit tek i vjetri në ditë, siç tha Danieli, dhe e amshuar është Mbretëria e tij."}]}]},{"n":"Tingulli Tërthor i Të Katërtit","sections":[{"k":"thirrtoret","part":"mbremesore","title":"Vargëzimet e Thirrtoreve","blocks":[{"t":"p","x":"Himn mbrëmësor dhe adhurim të arsyeshëm të blatojmë, o Krisht, se denjove të na mëshirosh me anë të Ngjalljes."},{"t":"p","x":"O Zot, o Zot, mos na hidh tej prej fytyrës sate, po denjo të na mëshirosh me anë të Ngjalljes."},{"t":"p","x":"Gëzohu, Sion e shenjtë, Nënë e Kishave, banesë e Perëndisë, se ti prite e para ndjesë mëkatesh me anë të Ngjalljes."},{"t":"p","x":"Fjala, që lindi para jetëve prej Perëndisë Atë, dhe në kohët e fundit vetë ajo u mishërua prej së Pamartuarës, duroi kryqëzim vdekjeje vullnetarisht dhe shpëtoi njeriun e vdekur prej kohësh me anë të Ngjalljes së tij."},{"t":"p","x":"Lavdërojmë Ngjalljen tënde prej së vdekurish, o Krisht, me anën e së cilës çlirove gjininë e Adamit prej tiranisë së Hadhit, dhe i dhurove botës, si Perëndi, jetën e amshuar dhe përdëllimin e madh."},{"t":"p","x":"Lavdi ty, o Krisht Shpëtimtar, Bir’ i Perëndisë, i Vetëmlindur, që u mbërtheve në Kryq, dhe u ngjalle prej varrit pas tri ditësh."},{"t":"p","x":"Ty të lavdërojmë, o Zot, që durove Kryq për ne vullnetarisht, dhe ty të falemi, o Shpëtimtar i tër’fuqishëm. Mos na hidh tej prej fytyrës sate, por dëgjona dhe shpëtona me anën e Ngjalljes sate, o Njeridashës."}]},{"k":"dogmatiku","part":"mbremesore","title":"Hyjlindësorja Dogmatike","blocks":[{"t":"p","x":"Mbreti i qiejve u shfaq mbi dhé nga njeridashja dhe u shoqërua me njerëzit; se, duke marrë trup nga Virgjëresha e Kulluar, dhe duke lindur prej saj me këtë trup, ky është një Bir me dy natyra, por me një hipostazë. Prandaj, duke e shpallur atë vërtet si Perëndi të përsosur dhe Njeri të përsosur, ne pohojmë Krishtin, Perëndinë tonë, të cilit lutju, o Nënë e Panusëruar, të mëshirohen shpirtrat tanë."}]},{"k":"pasvargjet","part":"mbremesore","title":"Pasvargjet","blocks":[{"t":"p","x":"U ngjite mbi Kryq, o Jisu, që zbrite prej qiellit; shkove te vdekja ti, o jeta e pavdekshme; Drit’ e vërtetë, për ata që ishin në errësirë; Ngjallja e të gjithë të rënëve. Ndriçimi dhe Shpëtimtari ynë, lavdi më ty."},{"t":"p","x":"Le të lavdërojmë Krishtin që u ngjall së vdekurish; se, duke marrë shpirt e trup, e ndan njërin nga tjetri me anë të Pësimit. Shpirti i pacenuar zbriti në Hadh, të cilin e plaçkiti; dhe në varr nuk njohu prishje, Trupi i shenjtë i Çliruesit të shpirtrave tanë."},{"t":"p","x":"Me psalme dhe me himne lavdërojmë, o Krisht, Ngjalljen tënde prej së vdekurish, me anën e së cilës na çlirove prej tiranisë së Hadhit, dhe na dhurove, si Perëndi, jetën e amshuar dhe përdëllimin e madh."},{"t":"p","x":"O Kryezot i të gjithëve, Bërës i pakuptueshëm i qiellit dhe i tokës, pësove me anë të Kryqit, dhe burove për mua mospësimin; dhe si denjove varrim dhe u ngjalle me lavdi, bashkëngjalle Adamin me dorë të gjith’fuqishme. Lavdi Ngjalljes sate të triditshme, me anën e së cilës na ke dhuruar jetën e amshuar dhe ndjesë mëkatesh, si i vetmi i Mëshirshëm."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"sub","x":"Hyjlindësorja"},{"t":"p","x":"Virgjëreshë e panusëruar, që linde trupërisht Perëndinë pa tregim, Nënë e Perëndisë së lartë, prit lutjet e shërbëtorëve të tu, o e Gjith’panjollshme, ti që u fal të gjithëve pastrim mëkatesh; prit lutjet tona tani, dhe lutu për shpëtimin e të gjithëve."}]},{"k":"perleshorja","part":"mengjesore","title":"Përlëshorja Ngjallësore","blocks":[{"t":"p","x":"Që lartazi zbrite, o i Zemërdhembshur, varrim denjove të triditshëm, që të na çlirosh neve prej pësimeve. O Zot, Jeta dhe Ngjallja jonë, lavdi më ty."}]},{"k":"hyjlindesorja","part":"mengjesore","title":"Hyjlindësorja Ngjallësore","blocks":[{"t":"p","x":"Ti që linde për ne prej Virgjëreshës dhe durove kryqëzim, o i Mirë, që plaçkite vdekjen me vdekje dhe rrëfeve Ngjalljen si Perëndi, mos i shpërfill ata që gatove me dorën tënde; trego njeridashjen tënde, o Mëshirëplotë; prit Hyjlindësen që të lindi të ndërmjetojë për ne; dhe shpëto, o Shpëtimtari ynë, një popull të dëshpëruar."}]},{"k":"ndenjesoret1","part":"mengjesore","title":"Pas Stihologjisë së parë, Ndenjësoret","blocks":[{"t":"p","x":"U ngjalle së vdekurish, o jeta e të gjithëve, dhe engjëll’ i ndritshëm u thërriste grave: Pushoni lotët, ungjillëzojini apostujt, thërrisni duke përhimnuar, se u ngjall Zoti Krisht, që denjoi të shpëtojë, si Perëndi, gjininë e njerëzve."},{"t":"sub","x":"Lavdi"},{"t":"sub","x":"Tin sofian"},{"t":"p","x":"Kur u ngrite prej varrit, o Zoti Krisht, porosite me gaz miroprurëset, t’u thoshin dishepujve, që u ngjalle së vdekurish; edhe rendi shën Pjetri dhe hodhi një sy mbi varr, dhe kur pa brenda dritën, çudinë se merrte vesh, po kur pa prokofin dhe pëlhurat e bardha, mënjanë të hedhura, edhe Trupi atje s’qe më, të thërriste me zë të madh: Zoti Krisht, lavdi më ty, se ti na shpëtove të gjithë si Perëndi; se ti ke qenë përjetë drita dhe diell’ i qiellit."},{"t":"sub","x":"Tani"},{"t":"sub","x":"Tin sofian"},{"t":"p","x":"Ti, o port’ qiellore, o shën Mari; ti, o mali i shenjtë plot me shkëlqim; o re udhëheqëse; ti, o shkallë e qiellshme; ti, o Parajs’ mendore për Evën shpëtuese; ti, o thesar i botës i shtrenjtë, i çmueshëm; ti, o Nën’ e shenjtë, ti shpëtimin na solle, nga fajet e prindërve dhe mallkimet e gjyshërve, të thërresim pra me lavdi, ndërmjeto pran’ Birit tënd, që t’u dhurojë ndjesën e mëkateve të gjith’ atyre që lusin lindjen tënde të hyjshme."}]},{"k":"ndenjesoret2","part":"mengjesore","title":"Pas Stihologjisë së dytë, Ndenjësoret","blocks":[{"t":"p","x":"Njerëzit vulosën varrin tënd, o Shpëtimtar, engjëlli rrokullisi gurin prej derës. Gratë të panë të ngjallur prej së vdekurish, dhe ato u ungjillëzuan dishepujve të tu në Sion, se u ngjalle, o jeta e të gjithëve, dhe i zgjidhe zinxhirët e vdekjes. O Zot, lavdi më ty."},{"t":"sub","x":"Lavdi"},{"t":"p","x":"Gratë që sollën miron e varrimit, dëgjuan një zë engjëllor prej varrit: Pushoni lotët, ndjeni gëzim në vend të hidhërimit, thërrisni duke përhimnuar, se u ngjall Zoti Krisht, që denjoi të shpëtojë, si Perëndi, gjininë e njerëzve."},{"t":"sub","x":"Tani"},{"t":"p","x":"Më ty gëzohet, o Hirplote, gjithë krijesa, sistemi i engjëjve dhe gjinia njerëzore, o tempull i shenjtëruar dhe Parajsë e arsyeshme, mburrje e virgjërisë, prej së cilës u mishërua dhe u bë djalë Perëndia ynë, që është para jetëve; se mitrën tënde e bëri fron, dhe barkun tënd e bëri më të gjerë se qiejt. Më ty gëzohet, o Hirplote, gjithë krijesa; lavdi më ty."}]},{"k":"degjimi","part":"mengjesore","title":"Dëgjimi","blocks":[{"t":"p","x":"Miroprurëset, duke qëndruar te varri jetëdhënës, kërkonin Kryezotin e pavdekshëm ndërmjet të vdekurve; dhe, si morën lajme të gëzueshme nga engjëlli, lajmëruan apostujt se u ngjall Zoti, që i fal botës përdëllimin e madh."}]},{"k":"shkallesat","part":"mengjesore","title":"Shkallesat","blocks":[{"t":"sub","x":"Antifoni i parë"},{"t":"p","x":"Që prej rinisë sime armiku më tundon, më djeg përmes kënaqësive, por unë, duke pasur besim te ti, o Zot, e thyej."},{"t":"p","x":"Ata që urrejnë Sionin, do të çrrënjosen si bari, se do t’ua presë Krishti zverqet me prerje mundimesh."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Shpirti i Shenjtë është jeta e të gjithëve, dritë prej drite, Perëndi i madh. E himnojmë bashk’ me Atin dhe me Fjalën."},{"t":"sub","x":"Antifoni i dytë"},{"t":"p","x":"Zemra ime le të mbrohet prej frikës sate, duke u përulur. Mos u largoftë prej teje, duke u lartësuar, o Mëshirëplotë."},{"t":"p","x":"Ai që ka pasur shpresë te Zoti, nuk do të ketë frikë atëherë, kur do t’i gjykojë dhe do t’i mundojë të gjitha me zjarr."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Me anën e Shpirtit të Shenjtë çdo i hyjshëm shikon dhe parathotë, bën çudira të larta, duke kënduar një Perëndi në tre; dhe ndonëse me tri shkëlqime, por një Hyjni mbretëron."},{"t":"sub","x":"Antifoni i tretë"},{"t":"p","x":"Të thirra, o Zot, vështrom’, dëgjomë mua që të thërres dhe pastromë, para se të më ngresh nga të këtejshmet."},{"t":"p","x":"Secili, duke zbritur te nëna e tij tokë, përsëri do të kthehet që të marrë mundime a shpërblime për ato që bëri në jetë."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Te Shpirti i Shenjtë është teologjia e Njësisë trishenjtore; se Ati ësht’ i panisshëm, prej të cilit lindi Biri pa kohë, dhe Shpirti i njëformshëm dhe i njëfronshëm, që bashkëndriti prej Atit."},{"t":"sub","x":"Antifoni i katërt"},{"t":"p","x":"Ç’gjë ka më të mirë a më të pëlqyeshme, sesa të banojnë bashkë vëllezërit? Se për këtë na premtoi Zoti jetë të amshuar."},{"t":"p","x":"Ai që stolis zambakët e arës, urdhëron që s’duhet të kujdeset njeriu për veshjen e tij."},{"t":"sub","x":"Lavdi dhe Tani"},{"t":"p","x":"Prej Shpirtit të Shenjtë, prej të vetmit shkak, çdo gjë merr shpërblimin e paqes; se Ai ësht’ Perëndi, pikërisht i bashkëqenshëm me Atin e me Birin."}]},{"k":"paravargu","part":"mengjesore","title":"Paravargu","blocks":[{"t":"p","x":"Zoti mbretëron përjetë; Perëndia yt, o Sion, brez pas brezi."},{"t":"sub","x":"Vargu: Lavdëro Zotin, o shpirti im."}]},{"k":"shkurtorja","part":"mengjesore","title":"Shkurtorja","blocks":[{"t":"p","x":"Kur dole prej varrit, ngrite të vdekurit dhe ngjalle Adamin. Eva vallëzon për Ngjalljen tënde, dhe anët e botës kremtojnë Ngjalljen tënde prej së vdekurish, o Mëshirëplotë."}]},{"k":"shtepia","part":"mengjesore","title":"Shtëpia","blocks":[{"t":"p","x":"Pasi plaçkite mbretërinë e Hadhit dhe pasi ngjalle të vdekurit, o Zemërgjerë, takove gratë miroprurëse, duke u dhuruar atyre gëzim në vend të hidhërimit, dhe apostujve të tu u tregove simbolet e fitores, o Shpëtimtari im Jetëdhënës, dhe krijesën e ndriçove, o Njeridashës. Prandaj dhe bota gëzohet për Ngjalljen tënde prej së vdekurish, o Mëshirëplotë."}]},{"k":"lavderimet","part":"mengjesore","title":"Vargëzimet e Lavdërimeve","blocks":[{"t":"p","x":"O Zot, megjithëse vajte në gjykatore dhe u gjykove prej Pilatit, ti nuk u largove nga froni, ku rri bashk’ me Atin; dhe, si u ngrite prej së vdekurish, e çlirove botën nga robëria e të huajit, si i Dhembshur dhe Njeridashës."},{"t":"p","x":"O Zot, megjithëse të vunë judenjtë si të vdekur në varr, si një Mbret që flije, ushtarët të ruanin, dhe të vulosën me vulë, si thesar të jetës; por u ngjalle dhe u fale shpirtrave tanë paprishjen."},{"t":"p","x":"O Zot, armë kundër djallit, Kryqin tënd na ke dhënë neve; se tmerrohet e dridhet, ngaqë nuk duron fuqinë e tij; se ngjall të vdekurit dhe shkatërron vdekjen. Prandaj i falemi Varrimit tënd dhe Ngjalljes."},{"t":"p","x":"Engjëlli yt, o Zot, që lëçiti Ngjalljen, rojat i trembi, dhe grave u thirri duke thënë: Si kërkoni të gjallin ndër të vdekurit? U ngjall se ishte Perëndi dhe i dhuroi botës jetën."},{"t":"p","x":"Pësove në Kryq, ti i papësuari nga Hyjnia. Denjove varrim të triditshëm, që të na çlirosh prej robërisë së armikut, dhe të na japësh jetën e pavdekshme me anën e Ngjalljes sate, o Njeridashës, Krisht Perëndi."},{"t":"p","x":"I falem dhe lavdëroj, dhe përhimnoj, o Krisht, Ngjalljen tënde prej varrit, me anë të së cilës na çlirove nga zinxhirët e pazgjidhshëm të Hadhit, dhe i dhurove botës, si Perëndi, jetën e amshuar dhe përdëllimin e madh."},{"t":"p","x":"Të paligjshmit vulosën varrin tënd dhe vunë roja që ta ruanin; por ti, si Perëndi i pavdekshëm dhe i tër’fuqishëm, u ngjalle pas tri ditësh."},{"t":"p","x":"Kur shkove te dyert e Hadhit, o Zot, dhe i dërrmove, robi kështu thërriste: Cili është ky që nuk dënohet në të përposhtmet e dheut, por e shembi burgun e vdekjes si një tendë? E prita si një njeri, dhe dridhem prej tij si prej Perëndie. O Shpëtimtar i tër’fuqishëm, lavdi më ty."}]}]}],"eothina":{"mel":"Ting. II  Tis Mathites","dergimsore":[{"x":"Mblidhuni me dishepujt tok në mal të Galilesë, ku po na thotë Zoti Krisht, se e ka marrë forcën kudo mbi dhé e mbi q’ellin, se atje Pagëzimin për gjithë kombet urdhëron, n’emër t’ Atit e Birit e Shpirtit t’Shenjt’, dhe kështu të mbetemi të bashkuar, përjetë pas premtimit t’tij, gjer në mbarim të jetës.","theo":"Gaz pate me dishepujt tok, o Mari Virgjëreshë, se e shikove Zotin Krisht, që u ngjall pas tri ditësh, qëndroj në mesin e tyre, dhe atje Pagëzimin për gjithë kombet urdhëroj, n’ emër t’ Atit e Birit e Shpirtit t’Shenjt’, të besojnë Ngjalljen e Shpëtimtarit, dhe të himnojmë ty me mall, Virgjëreshë dhe Zonjë."},{"x":"Kur panë miroprurëset gurin të rrokullisur prej varrit, po gëzoheshin se shikuan një engjëll, që ndrinte dhe vetëtinte, edhe atyre u thoshte: U ngrit nga varri Zoti Krisht, shokëve tok me Pjetrin t’u thoni pra, shkoni dhe shikojeni lart në malin, se ju pret në Galile, si u tha gjithë miqve.","theo":"Të përshëndeti engjëlli, duke thënë “gëzohu”, o Mari Hyjlindëse; engjëlli rrokullisi, gurin e rëndë prej varrit; edhe i pari na shfaqi se do të lindë Zoti Krisht, tjetri ndriti dhe thirri: Jisuj u ngjall, gaz të madh e jo vajtim dhe qarje, për gratë miroprurëse edhe për të gjith’ apostujt."},{"x":"Krishti u ngjall së vdekurish, pa dyshim dhe pa fjalë, Marisë pra në varr iu shfaq dhe pastaj e panë ata që shkonin në arë dhe në fund gjith’ apostujt, për Pagëzimin i dërgoj, n’emër të shën Trinisë dhe përsëri, fluturoj në q’ellin nga kishte zbritur, edhe këto i vërtetoj, me shumicë prej shenjash.","theo":"O Shpëtimtar, o Zoti Krisht, që shkëlqeve prej varrit, si dhëndri dhe dielli, dhe plaçkite Skëterrën, dhe vdekjen e shkatërrove, lutjet Nënës dëgjoja; dhe dritën tënde na dërgo, për të ndritur çdo zemër edhe çdo shpirt, dritë gjithë njerëzve, të baresin pas porosive që na dhe, në porositë e paqes."},{"x":"Të ndritur prej virtyteve, ejani t’i shikojmë në varr të jetëprurësit engjëjt shum’vezullues, të cilët u flasin grave, që kan’ ulur sytë, u ngjall Jisuj së vdekurish, rendni që ta shikoni brenda në varr, dhe të gjithë binduni si Pjetri, dhe që të gjithë mblidhuni që ta shikojmë Krishtin.","theo":"Gëzohuni, u the, o Zot, dhe mallkimin e vjetër, të hidhur të stërgjyshërve e shpërndave dhe solle gëzim për botën me Ngjalljen, Jetëdhënës; gëzona me anën e Hyjlindëses, ndritna zemrën dhe shpirtin me përdëllim, që të të thërresim, o Njeridashës: lavdi o Perëndi-njeri, Ngjalljes sate përjetë."},{"x":"Udh’ e jetës, o Zoti Krisht, me Kleopën dhe Lukën, si udhëtar barite tok, dhe n’ Emaus u njohe kur theve bukën në sofër; edhe zemrat dhe shpirtrat atyre po u digjeshin kur u flisje për Shkronjat në udhëtim, dhe shpjegoje dhimbjet që ke duruar. Le të thërresim pra u ngjall! Pjetrit iu duk me shokët.","theo":"Himnoj mëshirën që s’ka fund, Bërës i gjithësisë, se zbraze veten për çudi, edhe more natyrën më të përulur dhe vojte duke lindur prej Zonjës dhe Virgjëreshës si njeri; u varrose dhe zbrite në Hadh për ne, për shpëtimin dhe ndriçimin e botës, me lutjet e Hyjlindëses, o Zot i zemërdhembshur."},{"x":"U shfaqe si njeri, o Krisht Shpëtimtar nga natyra dhe hëngre me dishepujt tok, si u ngrite prej varrit, i çove të pagëzonin dhe pendim të lëçitnin, dhe shkove pranë Atit lart, si u dhe sigurimin që do t’u çosh Shpirtin Tërëshenjt’ dhe Ngushëllimtarin. Lavdi, o Perëndi-Njeri, ngjalljes sate përjetë.","theo":"O Krijues i botëve, o Zot i gjithësisë, prej Shën Marisë more trup, dhe njeri pa ndryshuar, për njerëzit na u bëre; na përtërite shpirtin e prishur prej mëkateve, ti që linde prej Nënës çuditërisht, pra të thërresim besërisht që të gjithë, me lavdërim dhe brohori: Zonj’ e botës, gëzohu."},{"x":"Kur mësuan nxënësit prej Marisë, që Zotin e ngritën që nga varr’ i Tij, rendi Pjetri dhe tjetri, nxënës’ i dashur i Krishtit, dhe, kur arritën, i panë, pëlhurat të mbështjellura dhe të hedhura tutje në cepin tej, dhe mbulesën përmbi kokë veç tyre, u qetësuan plotësisht gjersa panë Jisuin.","theo":"Çudira të papritura për mua ke punuar, o Shpëtimtar, o Zoti Krisht, se ke zbritur prej qellit, ke lindur prej Virgjëreshës, dhe mbi Kryq u mbërtheve, pësove vdekje përmbi Kryq, dhe u ngjalle prej varrit plot me lavdi, dhe prej vdekjes e çlirove njeriun. Lavdi më ty, o Zoti Krisht, Zot i gjith’fuqishëm."},{"x":"Engjëjt e ndritshëm, kur i pa brenda varrit të Zotit, Mari’ e shkretë u çudit, edhe Krishtin s’e njohu, po si kopshtar e pyeste: Thuajmë ku e vunë trupin e Zotit Jisu Krisht? Dhe kur i thirri emrin, e mori vesh. “Mos më prek tani”, i tha Shpëtimtari, “se shkoj në q’ell tek Ati im, vëllezërit lajmëroji”.","theo":"Ke lindur, o Hyjlindëse, njërin prej Shën Trinisë, me dy natyra Zotin Krisht, dhe me dy veprime, po si person ësht’ i njëshëm, pra ju lut pa pushuar, për hirin e besnikëve, që t’i shpëtojë nga kurthet që u kurdis i paudhi djall satan, se të gjithë në ty përikin, o Mari, Nënë dhe Virgjëreshë."},{"x":"Kur ishin mbyllur dyertë, ti, o Zot, brenda hyre, edhe me Shpirtin Tërëshenjt’ të gjith’ apostujt i mbushe, pasi u fryve me paqe dhe u fale të drejtën për ndjesën e mëkateve; dhe Thomait ia tregove pas tetë dit’sh brinjën edhe duart si një provë, me të thërresim: Ti je Zot, dhe ti je Perëndia.","theo":"Kur e shikove Birin tënd, që prej varrit të ngritur, o Zonjë dhe Hyjlindëse, o Mari Virgjëreshë, çdo hidhërim e harrove, që e durove si Nënë, kur mbërthyen përmbi Kryq, dhe me gaz u përmbushe dhe lumëri, dhe e lavdërove me apostujt. Ata pra që, Hyjlindëse, të lëçitin shpëtoji."},{"x":"Për peshk në gjol seç dolën sot, pranë Tiberiadës, shën Pjetri tok me nxënësit, të bijt’ e Zebedeut, me shën Thoman’ e me shokët; Krishti i porositi t’i hidhnin rrjetat djathtazi, zunë shum’ peshq pa masë, dhe ra me not Pjetri dhe i vajti Jisuit, i cili u duk së treti dhe tregoj, buk’ e peshq lart thëngjijve.","theo":"Zotit q’u ngjall së vdekurish, pas tri ditësh prej varrit, ju lut për ne, Hyjlindëse, që me mall të himnojmë, me këng’ e me lumërime, se të kemi përikje, dhe mbrojtëse përkrahëse, ndërmjetare përpara Zotit Jisu, se na ke besnikë dhe nderues, edhe prej teje gjithnjë presim, o Nënë, ndihmë."},{"x":"Pas Ngjalljes së triditshme, e pyete shën Pjetrin, o Zot, tri herë a më do, dhe bari e caktove, t’i ruante dhent’ e tua, dhe kur pa shokun tjetër, q’e donte shumë Zoti Krisht, e pyeti Jisuin: po ky ç’kërkon? Po Jisuj i tha: në dua të mbetet gjersa të kthehem përsëri, ç’ke ti, o Pjetër i dashur?","theo":"Mister’ i trembshëm dhe i madh, o çudi e papritur, me vdekjen vdekja plotësisht u dërrmua prej Zotit; të gjithë pra e himnojmë, o Zoti Krisht, o Perëndi, Ngjalljen tënde të shenjtë plot me lavdi edhe shën Marinë që të ka lindur; me ndërmjetimet e saj na shpëto prej Skëterrës."}],"lavdi":[{"tone":"Ting. I","x":"Kur dishepujt nxitonin drejt malit për lartësimin e Zotit prej dheut, ai u doli përpara. Dhe si iu falën dhe si mësuan pushtetin që iu ishte dhënë kudo, prej së larti u dërguan të predikonin Ngjalljen prej së vdekurish dhe rivendosjen në qiej, të cilëve u premtoi se do të jetë me ta përjetë: Krishti, Perëndia i vërtetë dhe Shpëtimtari i shpirtrave tanë."},{"tone":"Ting. II","x":"Kur me miro afroheshin drejt varrit gratë tok me Marinë, dhe pyesnin veten se si do ta shihnin të përmallshmin sërish, panë gurin e rrokullisur dhe një djalosh të perëndishëm, që ua lehtësoi shqetësimin e shpirtit se: U ngjall Zoti Jisu, - u tha. Prandaj lëçituni dishepujve të tij lëçitës të rendin drejt Galilesë dhe atje do ta shohin të ngjallur prej së vdekurish, si Jetëdhënës dhe Zot."},{"tone":"Ting. III","x":"Kur Maria Magdalena ungjillëzonte Ngjalljen prej së vdekurish dhe shfaqjen e Shpëtimtarit, dishepujt dyshues qortoheshin për ashpërsinë e zemrës. Por, pasi u armatosën prej shenjave dhe çudive, u dërguan të predikonin. Dhe ti, o Zot, u ngjite pranë Atit të kryendritshëm. Edhe ata lëçitën fjalën kudo, duke e vërtetuar përmes mrekullive. Prandaj ne, që u ndriçuam prej tyre, lavdërojmë Ngjalljen tënde prej së vdekurish, o Zot njeridashës."},{"tone":"Ting. IV","x":"Herët në mëngjes gratë shkuan te varri yt, o Krisht, por nuk e gjetën Trupin tënd, për të cilin kishin mall. Prandaj, tek po çuditeshin, iu shfaqën ata që iu ndritnin rrobat dhe u thanë: Si kërkoni të gjallin ndër të vdekurit? U ngrit, siç paratha. Përse i harruat fjalët e tij? Dhe si u bindën prej tyre, lëçitën ato që panë, por lajmi i mirë u dukej si marrëzi, ngaqë dhe dishepujt kishin rënë në plogështi; por Pjetri rendi dhe, pasi pa, lavdëroi me vete çuditë e tua."},{"tone":"Ting. Tërth. I","x":"Sa të urta janë gjykimet e tua, o Krisht! Si i dhe Pjetrit të kuptonte Ngjalljen tënde vetëm prej pëlhurave? Ndërsa Lukës dhe Kleopës, teksa udhëtoje me ta, si nuk ua shfaqe veten menjëherë kur bisedoje? Prandaj, pra, u qortove, si banuesi i vetëm në Jerusalem që nuk dije çfarë kishte ndodhur atje së fundmi. Por ti, që i rregullon të gjitha për të mirën e krijesës, u shpjegove atyre profecitë që flisnin për ty dhe, me të bekuar bukën, u njohe prej tyre, të cilëve më parë iu digjeshin zemrat që të të njihnin. Dhe më pas, dishepujve që ishin mbledhur bashkë, ua lëçitën më zë të lartë Ngjalljen, me anën e së cilës mëshirona."},{"tone":"Ting. Tërth. II","x":"Ti, o Krisht, që je paqja e vërtetë e Perëndisë për njerëzit, kur u dhuroje paqen tënde dishepujve pas Ngjalljes, i trembe ata, ngaqë menduan se shikonin një fantazmë. Por ua qetësove shpirtin e trazuar, duke u treguar duart dhe këmbët e tua; por, meqë ende nuk besonin kur hëngre para tyre dhe u solle ndërmend mësimet, ua ndriçove mendjen të kuptonin Shkrimet; dhe si iu dhe premtimin atëror dhe pasi i bekove, u ngjite në qiell. Prandaj dhe ne, bashk’ me ta, ty të falemi, o Zot, lavdi më ty."},{"tone":"Ting. i Rëndë","x":"Ja errësirë dhe mëngjes; dhe ti, o Mari, përse qëndron pranë varrit me mendje fort të errësuar? Prandaj po pyet ku e kanë vënë Jisuin. Por shiko dishepujt që rendën bashk’ se si u bindën për Ngjalljen prej pëlhurave dhe prej rizës, dhe kujtuan Shkrimet që flisnin për të. Bashkë me ta, edhe ne që besuam përmes tyre, të përhimnojmë ty, Krishtin jetëdhënës."},{"tone":"Ting. Tërth. IV","x":"Lotët e nxehtë të Marisë nuk u derdhën më kot; se ja ku u denjësua të mësohet prej engjëjsh e të të shohë ty, o Jisu; por si grua e pafuqishme, mendjen e kishte te gjërat tokësore! Prandaj nuk e le të të prekte, o Krisht. Mirëpo dërgohet si lëçitëse te dishepujt e tu, të cilëve u dha lajmin e mirë dhe i lajmëroi për ngjitjen tënde në trashëgiminë Atërore. Bashkë me të, denjësona edhe ne për shfaqjen tënde, o Zot dhe Zotërues."},{"tone":"Ting. Tërth. I","x":"Në orët e fundit, në mbrëmjen e ditës së parë të javës, qëndrove përpara miqve, o Krisht, dhe vërtetove Ngjalljen tënde prej së vdekurish kur hyre nga dyert e mbyllura, mrekullinë me mrekulli. I mbushe dishepujt me gëzim, dhe Shpirtin e Shenjtë u dhurove. U fale atyre pushtetin të ndjejnë mëkatet, dhe Thomanë nuk e le të përmbytej nga shqota e pabesisë. Prandaj falna edhe ne dijen e vërtetë dhe ndjesë mëkatesh, o Zot i  zemërdhembshur."},{"tone":"Ting. Tërth. II","x":"Pas zbritjes në Hadh dhe Ngjalljes prej së vdekurish, dishepujt ishin të hidhëruar, ashtu siç ishte e natyrshme, për ndarjen nga ti, o Krisht; iu kthyen punës: dhe përsëri morën varkat dhe hodhën rrjetat, por nuk zunë asgjë. Por ti, u shfaqe, o Shpëtimtar, si Zot i gjithësisë, dhe urdhërove t’i hidhnin rrjetat në të djathtë. Menjëherë fjala vepër u bë, një shumicë e madhe peshqish u zu dhe një darkë e çuditshme ishte gati mbi dhé, në të cilën morën pjesë dishepujt e tu atëherë; denjësona edhe ne ta shijojmë tani shpirtërisht, o Zot njeridashës."},{"tone":"Ting. Tërth. IV","x":"Kur iu shfaqe dishepujve, o Shpëtimtar, pas Ngjalljes sate, porosite Simonin t’i ruante delet e tua, duke i kërkuar t’i kulloste me kujdes si shpërblim të dashurisë së tij. Prandaj i thoshe: “Në më do, o Pjetër, kulloti qengjat e mi, kulloti delet e mia”. Dhe ai, duke treguar menjëherë dashurinë e tij, pyeste për dishepullin tjetër. Me ndërmjetimet e tyre, o Krisht, ruaje grigjën tënde nga ujqërit që e përçajnë atë."}]}};
